REPO = Path(__file__).resolve().parents[1]
if str(REPO) not in sys.path:
    sys.path.insert(0, str(REPO))

MODULES = ("keys", "corr", "banner", "schedule", "bars", "audit", "guard", "resume", "readrule",
           "testing", "scaffold", "runner_qwen", "runner_olmo", "verify", "stages", "gcal", "gshape")
SCHED_DIR = REPO / "data" / "m" / "schedules"
UNITS = ("Q-F0", "OLMo-sft", "OLMo-dpo", "OLMo-instruct", "Q-F3")
STAGE_CMDS = ("time", "id", "qual", "campaign")

# §8's step words, quoted from m:358 (Q-F0 steps 10, 12, 14, 16; the OLMo track) and
# m:361 (Q-F3, step 19).
# PIN (Code, declared at LOCK v0.1): the stage subcommands refuse with exit 2 until
# their step; the message names the step and quotes its words.
STEP_WORDS = {
    "time": (10, "G-TIME-F0 (2 sessions)"),
    "id": (12, "G-ID-F0m"),
    "qual": (14, "G-F0m-Qwen (24 sessions); the seat's read under §3's rule; entry"),
    "campaign": (16, "Q-F0 campaign (detached, checkpointed, A0/A0s interleaved by §2.1's rule, "
                     "per-arm stop at floor, §6 monitoring; verify once; end the session)"),
}
# time, id, qual and campaign are wired (steps 10, 12, 14 and 16): main sends them to _run_stage, so
# refusal() no longer reaches their entries on Q-F0; the entries stay as declared at LOCK v0.1.
OLMO_WORDS = ("OLMo track, from step 9 when a box exists, in parallel, per checkpoint as §3.3 "
              "(the PI's go for a pod start is required; runpod MCP re-authorisation first)")
QF3_WORDS = "Begins only after the `POSTING v1` entry exists"


def refusal(cmd: str, unit: str) -> str:
    """The refusal line of a stage subcommand at step 4."""
    if unit == "Q-F3":
        return (f"not licensed until step 19: §8 step 19 -- \"{QF3_WORDS}\"; no F3 code in step 4")
    if unit != "Q-F0":
        if cmd == "id":
            return f"refused: no G-ID on OLMo (uncached path, m:267); {unit} has no id stage"
        return (f"not licensed until step 9: §3.3 track (from step 9, a box and the PI's go) -- "
                f"§8: \"{OLMO_WORDS}\"")
    n, words = STEP_WORDS[cmd]
    return f"not licensed until step {n}: §8 step {n} -- \"{words}\""


def build_schedules(out: Path) -> int:
    from valence_core.m import schedule
    before = {p.name: p.read_bytes() for p in out.glob("*.json")} if out.exists() else {}
    try:
        shas = schedule.write_schedule_files(out)
    except RuntimeError as e:
        print(f"REFUSED: {e}", flush=True)
        return 1
    written = sorted(n for n in shas if before.get(n) != (out / n).read_bytes())
    total = sum((out / n).stat().st_size for n in shas)
    man = hashlib.sha256((out / schedule.MANIFEST_NAME).read_bytes()).hexdigest()
    print(f"SCHEDULES {out}: {len(shas)} files, {total} bytes, manifest sha256 {man}; "
          f"{len(written)} written, {len(shas) - len(written)} unchanged", flush=True)
    probs = schedule.verify_schedule_dir(out)
    print("VERIFY clean" if not probs else f"VERIFY PROBLEMS {probs}", flush=True)
    return 0 if not probs else 1


# --- G-PORT (§8 step 5, m:275) -------------------------------------------------------------
GPORT_NAME = "Q-F0_G-PORT.json"
GPORT_CRITERION = "64/64 archived CORR transcripts' harness-written lines reproduced (m:275)"
GPORT_N = 64
_SHA16 = re.compile(r"^[0-9a-f]{16}$")


def gport_path(out: Path | None) -> Path:
    """The G-PORT artifact's path.

    PIN (Code, declared at LOCK v0.1): with no --out it is guard.GATES_DIR /
    Q-F0_G-PORT.json (data/m/gates/, beside the G-ID artifact; tracked by .gitignore's
    data/m/gates allowlist); --out DIR is a test directory and goes through
    resume.refuse_canonical_out first, so no test run can land under data/m.
    """
    from valence_core.m import guard, resume
    if out is None:
        return guard.GATES_DIR / GPORT_NAME
    return resume.refuse_canonical_out(out) / GPORT_NAME


def run_gport(out: Path | None = None, *, rows: list[dict] | None = None,
              f1_sha16: str | None = None) -> int:
    """G-PORT: replay every archived f1 CORR row; write the artifact; 0 PASS / 4 STOP / 1 refused.

    ``rows`` / ``f1_sha16`` are the selftest's seam (a tampered or shortened row list); a
    run given rows is refused unless ``out`` names a test directory. Without them the rows
    are scaffold.load_f1_rows()'s (sha16 pinned, a drift a SystemExit before any replay).
    """
    from valence_core.m import resume, scaffold, stages
    if rows is None:
        if f1_sha16 is not None:
            raise ValueError("run_gport: f1_sha16 is given only with supplied rows")
    else:
        if out is None:
            raise SystemExit("G-PORT REFUSED: supplied rows (a selftest) never write the canonical "
                             "artifact; name a test directory")
        if type(f1_sha16) is not str or not _SHA16.match(f1_sha16):
            raise ValueError("run_gport: supplied rows need their 16-hex sha16")
    path = gport_path(out)                         # a canonical --out is refused before any replay
    if rows is None:
        rows, f1_sha16 = scaffold.load_f1_rows(), scaffold.F1_SESSIONS_SHA16
    pool, _renders = scaffold.pool_and_renders()
    corr_rows = [r for r in rows if isinstance(r, dict) and r.get("arm") == "CORR"]
    n_ok, mismatches = 0, []
    for r in corr_rows:
        try:
            probs = list(scaffold.replay_f1_row(r, pool))
        except (KeyError, TypeError, ValueError, IndexError, AttributeError, RuntimeError) as e:
            # PIN (Code, declared at LOCK v0.1): a row the replay cannot walk is a mismatch
            # (the exception's type only is printed and recorded), never a crash or a pass.
            probs = [f"replay raised {type(e).__name__}"]
        s = r.get("session")
        if probs:
            mismatches.append({"s": s, "problems": probs})
            print(f"gport s={s} MISMATCH: {'; '.join(probs)}", flush=True)
        else:
            n_ok += 1
            print(f"gport s={s} ok", flush=True)
    n = len(corr_rows)
    # PIN (Code, declared at LOCK v0.1): PASS iff every CORR row reproduces AND there are
    # exactly 64 of them (m:275 "64/64 or STOP"); the artifact's keys are exactly these.
    verdict = "PASS" if n_ok == n == GPORT_N else "STOP"
    art = {"criterion": GPORT_CRITERION, "unit": "Q-F0", "n_rows": n, "n_ok": n_ok,
           "mismatches": mismatches, "f1_sessions_sha16": f1_sha16,
           "package_sha256": resume.package_sha256(), "verdict": verdict}
    text = resume.json_text(art, indent=1)
    rc = stages.exit_code(verdict)
    if path.exists() or path.is_symlink():
        try:
            same = path.is_file() and not path.is_symlink() and path.read_text(encoding="utf-8") == text
        except (OSError, UnicodeDecodeError):
            same = False
        if not same:
            # PIN (Code, declared at LOCK v0.1): an existing G-PORT artifact is never
            # overwritten; identical bytes are accepted as they are (a re-run changes nothing).
            print(f"REFUSED: G-PORT ARTIFACT EXISTS at {path} with different bytes -- it is never "
                  f"overwritten (this run's verdict {verdict} is not recorded)", file=sys.stderr, flush=True)
            rc = 1
    else:
        path.parent.mkdir(parents=True, exist_ok=True)
        resume.atomic_write_json(path, art, indent=1)
    print(f"  G-PORT {n_ok}/{n} archived CORR transcripts reproduced", flush=True)
    return rc


# --- G-CAL (§8 step 6, m:176, m:358) ---------------------------------------------------------------
# PIN (Code, declared at LOCK v0.1): gcal exits 0 on PASS (or a model-free artifact written or
# identical), 4 on FAIL or a STOP, 2 on a refusal (nothing generated past it).
# PIN (Code, declared at LOCK v0.1): after the G-CAL-specific clauses (GcalRefusal -> 2,
# GcalStop -> 4), any other SystemExit reaching a gcal driver -- corr.CorrStop (a pool or
# roster pin), guard.assert_insulated's (the quarantined module loaded mid-run),
# qwen_or_explain's (the loader) -- is a STOP: exit 4, its message on stderr.
GCAL_EXIT = {"PASS": 0, "FAIL": 4}


def _load_qwen():
    """The Qwen adapter, through the package's one loader (valence_core.adapters.qwen_or_explain),
    with QWEN_MODEL_ID passed explicitly (the snapshot check reads the same constant)."""
    from valence_core.adapters import qwen_or_explain
    return qwen_or_explain(__file__, model_id=QWEN_MODEL_ID)


def run_gcal_model_free(out: Path | None = None) -> int:
    """G-CAL's model-free step: the artifact (data/m/gates/G-CAL_model-free.json) and the seat
    read request beside it; 0 written or identical, 2 refused, 4 STOP."""
    from valence_core.m import gcal
    try:
        res = gcal.write_model_free(out)
    except gcal.GcalRefusal as e:
        print(f"REFUSED: {e}", file=sys.stderr, flush=True)
        return 2
    except gcal.GcalStop as e:
        print(f"STOP: {e}", file=sys.stderr, flush=True)
        return 4
    except SystemExit as e:
        print(f"STOP: {e}", file=sys.stderr, flush=True)
        return 4
    art = res["artifact"]
    f1, ror, c = art["f1_012"], art["renders_of_record"], art["conditions"]
    print(f"G-CAL model-free (a) f1 corrupt() at 0.12: renders sha16 {f1['renders_sha16']} (calib "
          f"corr_sha {'matches' if f1['renders_sha_matches_calib'] else 'DIFFERS'}), {f1['n_changed']} "
          f"letters changed, condition (1) {f1['n_cond1']}/16, condition (2) {f1['n_cond2']}/16; covariate "
          f"of record {f1['covariate_of_record']} ({art['f1_012_covariate_quote']['as_quoted_in_m176']})",
          flush=True)
    print(f"G-CAL model-free (b) renders of record sha256 {ror['renders_sha256']}; n_eligible "
          f"{ror['n_eligible']}; k {ror['k']} (sum {ror['k_sum']}); roster skips {ror['roster_skips']}",
          flush=True)
    print(f"G-CAL model-free (c) roster assertion on the renders, both rosters: "
          f"{'clean' if art['roster_assertion']['pass'] else 'HITS'}", flush=True)
    print(f"G-CAL model-free (d) conditions: (1) {c['1']['verdict']} {c['1']['n_pass']}/{c['1']['n']}; "
          f"(2) {c['2']['verdict']} {c['2']['n_pass']}/{c['2']['n']}; (3) {c['3']}; (4) {c['4']}", flush=True)
    print(f"G-CAL model-free artifact: {res['path']} ({res['how']})", flush=True)
    print(f"G-CAL seat read request: {res['seat_path']} ({res['seat_how']})", flush=True)
    return 0


def run_gcal_completability(out: Path | None, resume_run: bool, proposal_file: str, *,
                            adapter_factory=None) -> int:
    """G-CAL's condition (4) on Qwen (m:176). The proposal's sha256 is computed here from its
    COMMITTED blob; every refusal that needs no model runs before the model loads.

    PIN (Code, declared at LOCK v0.1): ``adapter_factory`` is the selftest's seam (a scripted
    stub); without it the adapter is Qwen through qwen_or_explain, which writes the canonical
    paths only, so ``--out`` (a test directory) is refused on that path before any load."""
    from valence_core.m import gcal, resume, stages
    p = Path(proposal_file)
    p = p if p.is_absolute() else REPO / p
    try:
        rel = p.resolve().relative_to(REPO.resolve()).as_posix()
    except ValueError:
        print(f"REFUSED: --proposal-file {proposal_file} lies outside the repository", file=sys.stderr,
              flush=True)
        return 2
    probs, data = stages._committed(rel)
    if probs or data is None:
        print(f"REFUSED: --proposal-file {rel}: {probs} (G-CAL's identity is this document's hash, m:267; "
              f"it must be committed)", file=sys.stderr, flush=True)
        return 2
    sha = hashlib.sha256(data).hexdigest()
    if out is not None and adapter_factory is None:
        print("REFUSED: gcal completability --out names a test directory; the Qwen run writes "
              "data/m/gates and data/m/ckpt only (nothing loaded)", file=sys.stderr, flush=True)
        return 2
    out_path = None
    if out is not None:
        try:
            out_path = resume.refuse_canonical_out(out) / gcal.COMPLETABILITY_NAME
        except SystemExit as e:
            print(f"REFUSED: {e}", file=sys.stderr, flush=True)
            return 2
    try:
        if adapter_factory is None:
            gcal.precheck(out_path=None, resume=resume_run, proposal_file=rel, proposal_sha256=sha,
                          stub=False)
            adapter_factory = _load_qwen
        adapter = adapter_factory()
        res = gcal.run_completability(adapter, out_path=out_path, resume=resume_run, proposal_file=rel,
                                      proposal_sha256=sha)
    except gcal.GcalRefusal as e:
        print(f"REFUSED: {e}", file=sys.stderr, flush=True)
        return 2
    except gcal.GcalStop as e:
        print(f"STOP: {e}", file=sys.stderr, flush=True)
        return 4
    except SystemExit as e:
        print(f"STOP: {e}", file=sys.stderr, flush=True)
        return 4
    return GCAL_EXIT[res["verdict"]]


# --- G-SHAPE-F0 (§8 step 7, m:277) -----------------------------------------------------------
def run_gshape(out: Path | None = None) -> int:
    """G-SHAPE-F0: the model-free scoring-scope gate; 0 PASS, 2 refused, 4 STOP.

    PIN (Code, declared at LOCK v0.1; PIN-S8): GshapeRefusal -> 2 (nothing written); GshapeStop
    -> 4 (a precondition STOP, no artifact); any other SystemExit reaching the driver -> 4 with its
    message (gcal's PIN); a STOP verdict is written with its evidence and exits 4 (G-PORT's
    precedent). Code escalates a STOP to the seat and never self-adjudicates."""
    from valence_core.m import gshape
    try:
        res = gshape.write(out)
    except gshape.GshapeRefusal as e:
        print(f"REFUSED: {e}", file=sys.stderr, flush=True)
        return 2
    except gshape.GshapeStop as e:
        print(f"STOP: {e}", file=sys.stderr, flush=True)
        return 4
    except SystemExit as e:
        print(f"STOP: {e}", file=sys.stderr, flush=True)
        return 4
    for line in gshape.summary_lines(res):
        print(line, flush=True)
    return gshape.EXIT[res["artifact"]["verdict"]]


