def campaign_floors() -> dict[str, int]:
    """The campaign's floors per arm, in CAMPAIGN_LAUNCH_COUNTS' order: schedule.FLOORS under
    CAMPAIGN_LOCKED_PATH (a per-path entry) or as it stands (one floor for both paths)."""
    from valence_core.m import schedule
    fl = {t: schedule.FLOORS[t] for t, _ in CAMPAIGN_LAUNCH_COUNTS}
    return {t: (v[CAMPAIGN_LOCKED_PATH] if isinstance(v, dict) else v) for t, v in fl.items()}


# PIN (Code, declared at the campaign wiring): the step-14 read's Q3, the driver-only redaction "scheduled
# with the campaign wiring": resume._check_state's "hour_cap_ms_used X != the sessions' Y ms" (its CHECKPOINT
# STATE INCONSISTENT line, which "is not quoted or computed against before VERDICTS and goes to the seat in a
# sealed form") reaches the driver as a SystemExit's text, printed at its STOP or inside its REFUSED line --
# from any checkpoint a stage reads (its own, the prior stage's), whose Y sums every session's time, a
# contrast arm's included. ``redact_totals`` rewrites the two figures, wherever the text stands in a printed
# line (bare, or inside a list's repr however deeply nested, its apostrophe escaped by any number of
# backslashes or not), into "the driver prints that the totals
# differ" (Q3) and the rest of the line is unchanged; every REFUSED and STOP line _run_stage prints passes
# through it (``_say``), and stage_precheck returns its problems through it. The line arises only where resume
# runs _check_state -- _read (read_checkpoint, load_or_init, persist_end), write_checkpoint, assert_writable --
# which in this driver is the stage subcommands' path, _run_stage: gport and gshape keep no checkpoint, and gcal
# reads and writes its own (json.loads, resume.atomic_write_json) without _check_state. Its scope is Q3's line:
# the package's other messages are printed as the package words them -- "state.hour_cap_ms_used = X" fires only
# on a value that is not a non-negative int, and a session's malformed seconds only on one that is not a
# non-negative number, neither of them a total the package wrote.
# No package revision for Q-F0 (Q3); nothing under valence_core/m changes.
TOTALS_RX = re.compile(r"hour_cap_ms_used \S+ != the sessions\\*' \S+ ms")
TOTALS_REDACTED = ("hour_cap_ms_used and the sessions' total differ (both figures redacted at the driver's "
                   "print: the step-14 read, Q3)")


def redact_totals(text: str) -> str:
    """``text`` with every occurrence of Q3's two totals replaced by TOTALS_REDACTED."""
    return TOTALS_RX.sub(TOTALS_REDACTED, text)


def _say(line: str) -> None:
    # a REFUSED or STOP line of _run_stage: redacted (Q3), then printed to stderr
    print(redact_totals(line), file=sys.stderr, flush=True)


def stage_identity_extra(stage: str, proposal_file: str, lock_file: str, *, analyzer_sha256: str,
                         package_sha256: str, renders_sha16: str) -> tuple[dict | None, list[str]]:
    """A driver stage's identity_extra and the problems that stop it being built ((None,
    problems)).

    PIN (Code, declared at LOCK v0.2): the proposal's and the lock's sha256 are computed here
    from their COMMITTED blobs (stages._committed: committed at HEAD, working tree identical;
    G-CAL completability's precedent for the proposal). The lock is TIME_LOCK_FILE (lock §0),
    and its committed text must name the proposal's sha256 in full, anywhere in it (lock §1
    binds the proposal in its table; a committed file the lock names that is not a proposal is
    refused by the precheck's banner check): the licence's (b) and (c) compare each file with a
    hash taken from that same file, so these two checks are what tie the run to LOCK-m-F0.md as
    committed at HEAD (whichever revision that is; the LICENCE line prints its sha16) and that
    lock to the proposal. The analyzer's and the package's sha256 and the renders' sha16 are the
    values the command line gives -- the lock's -- and are never derived here from the bytes they
    are checked against: the licence checks the first two at stage start ((d)-(f)) and
    _renders_of_record the third. G-TIME-F0 carries locked_path TIME_LOCKED_PATH; G-ID-F0m
    carries none (m:282: the path is locked at v0.2, after G-ID). prior_proposal_sha256s is
    omitted (none under LOCK v0.1, lock §0)."""
    from valence_core.m import stages
    if stage not in DRIVER_STAGES:
        raise ValueError(f"stage_identity_extra: {stage!r} is not one of {DRIVER_STAGES}")
    probs: list[str] = []
    extra: dict = {}
    lock_text = ""
    for key, given in (("proposal", proposal_file), ("lock", lock_file)):
        p = Path(given)
        p = p if p.is_absolute() else REPO / p
        try:
            rel = p.resolve().relative_to(REPO.resolve()).as_posix()
        except (ValueError, OSError, RuntimeError):
            probs.append(f"--{key}-file {given}: lies outside the repository (or does not resolve)")
            continue
        if key == "lock" and rel != TIME_LOCK_FILE:
            probs.append(f"--lock-file {rel}: {stages.stage_name(TIME_UNIT, stage)} cites {TIME_LOCK_FILE} "
                         f"(lock §0)")
            continue
        cp, data = stages._committed(rel)
        if cp or data is None:
            probs.append(f"--{key}-file {rel}: {cp} (the identity hashes its committed blob)")
            continue
        extra[f"{key}_file"] = rel
        extra[f"{key}_sha256"] = hashlib.sha256(data).hexdigest()
        if key == "lock":
            lock_text = data.decode("utf-8", "replace")
    if probs:
        return None, probs
    if extra["proposal_sha256"] not in lock_text:
        return None, [f"--proposal-file {extra['proposal_file']}: its sha256 "
                      f"{extra['proposal_sha256'][:16]}... is not named in full in {TIME_LOCK_FILE}'s "
                      f"committed text (lock §1 binds the proposal of record)"]
    extra.update(analyzer_sha256=analyzer_sha256, package_sha256=package_sha256,
                 renders_sha16=renders_sha16)
    if stage == "time":
        extra["locked_path"] = TIME_LOCKED_PATH
    # PIN (Code, declared at LOCK v1.0): G-F0m-Qwen runs under LOCK-m-F0 v0.2 (stages.py:976-980,
    # "qualification v0.2"), whose committed text names the path (v0.2 §1) and the weights of
    # record (v0.2 §4); a governing lock whose committed text names any of QUAL_LOCK_PATH_TEXT,
    # QWEN_REVISION or QWEN_MODEL_ID not at all -- v0.1's blob, for one -- is refused here, before
    # the precheck, and the stage then carries QUAL_LOCKED_PATH. prior_proposal_sha256s stays
    # omitted (none under v0.2, v0.2 §0).
    if stage == "qual":
        absent = [x for x in (QUAL_LOCK_PATH_TEXT, QWEN_REVISION, QWEN_MODEL_ID) if x not in lock_text]
        if absent:
            return None, [f"--lock-file {TIME_LOCK_FILE}: its committed text does not name {absent} (LOCK-m-F0 "
                          f"v0.2 §§1, 4: the path and the weights of record G-F0m-Qwen runs under)"]
        extra["locked_path"] = QUAL_LOCKED_PATH
    # PIN (Code, declared at the campaign wiring): the campaign runs under LOCK-m-F0 v1.0 (stages.py:976-980,
    # "the campaign v1.0"), whose committed text carries v1.0 §4's line forms (CAMPAIGN_LOCK_LINES, tested as
    # substrings), the path and the weights of record (v1.0 §7, carried from v0.2 §§1, 4); a governing lock
    # whose committed text lacks any of them -- v0.2's blob, for one -- is refused here, before the precheck,
    # and the stage then carries CAMPAIGN_LOCKED_PATH. prior_proposal_sha256s stays omitted (none under v1.0:
    # "The proposal is unchanged", v1.0 §0).
    if stage == "campaign":
        absent = [x for x in CAMPAIGN_LOCK_LINES + (QUAL_LOCK_PATH_TEXT, QWEN_REVISION, QWEN_MODEL_ID)
                  if x not in lock_text]
        if absent:
            return None, [f"--lock-file {TIME_LOCK_FILE}: its committed text does not name {absent} (LOCK-m-F0 "
                          f"v1.0 §§4, 7: the launch counts, the hour cap, the path and the weights of record the "
                          f"campaign runs under)"]
        extra["locked_path"] = CAMPAIGN_LOCKED_PATH
    try:
        stages._extra(extra, stage=stage, sub="qwen", stub=False)
    except ValueError as e:
        return None, [str(e)]
    return extra, []


def time_identity_extra(proposal_file: str, lock_file: str, **kw) -> tuple[dict | None, list[str]]:
    """G-TIME-F0's identity_extra (``stage_identity_extra`` for "time")."""
    return stage_identity_extra("time", proposal_file, lock_file, **kw)


def driver_problems() -> tuple[list[str], str | None]:
    """(problems, sha256) of this driver's bytes: [] and the sha256 of its committed blob when
    it is committed at HEAD with the working tree's bytes (stages._committed); else the
    problems and None.

    PIN (Code, declared at LOCK v0.2): the PI's word of 2026-10-12, in the sentence giving the
    seat's answer, directs "record the driver's new sha256 in the G-TIME-F0 entry and in LOCK
    v0.2"; the seat's step-10 read (Q2) makes the like record a condition of every wiring of its
    kind: "the new blob's sha256 printed by the DRIVER line and recorded in the entry of the stage
    it wires and in the next lock revision — v0.2 for `id`, v1.0 for `qual`, and for `campaign`,
    which follows v1.0, the campaign's launch entry". ``_run_stage``'s Qwen path refuses an
    uncommitted driver and prints the DRIVER line from this one call before the load, so the value
    recorded is a value the run logged."""
    from valence_core.m import stages
    cp, data = stages._committed(DRIVER_REL)
    if cp or data is None:
        return list(cp) or [f"{DRIVER_REL}: unreadable"], None
    return [], hashlib.sha256(data).hexdigest()


def qwen_snapshot(*, model_id: str | None = None, cache_dir: str | os.PathLike | None = None,
                  environ: dict | None = None, cwd: str | os.PathLike | None = None) -> tuple[list[str], dict | None]:
    """(problems, info) of the Qwen weights an offline load reads; [] and the info when clear.

    PIN (Code, declared at LOCK v0.2): the seat's step-10 read, Q5, rules the load ("For every
    later Qwen stage of Q-F0: an offline load, with the snapshot id recorded in each raw's header
    and in each stage's entry") and leaves the print to Code ("Code may have the driver's
    precheck print the snapshot id (the `refs/main` value and the snapshot directory) as a line
    of the raw ... Code's choice"). Code takes the print, and its own refusals before the load,
    each mirroring how the load resolves the weights (jlens_qwen.model.load -> mlx_lm.load ->
    mlx_lm.utils._download -> huggingface_hub.snapshot_download): HF_HUB_OFFLINE must be exactly
    "1" (Code's form of Q5's offline load); MLXLM_USE_MODELSCOPE must not be "true" in any case
    (mlx_lm tests it so, and would take modelscope's downloader); no path or link named like the
    model id may exist relative to the working directory (mlx_lm loads an existing one before the
    hub cache; a dangling link is refused conservatively); the hub cache's
    `refs/main` for QWEN_MODEL_ID must be, as raw file text, a 40-hex revision whose snapshot
    directory exists and holds config.json, tokenizer.json, model.safetensors.index.json and
    every weight file the index names (each a plain file name, resolving to a file); and the
    hub's own offline resolution with mlx_lm's patterns (snapshot_download, local_files_only)
    must succeed and return that same directory. The cache is huggingface_hub's HF_HUB_CACHE.
    info: model_id, revision, snapshot_dir, n_snapshots (snapshot directories of the model's
    cache repo), offline."""
    env = os.environ if environ is None else environ
    probs: list[str] = []
    if env.get(HF_OFFLINE_ENV) != "1":
        probs.append(f"{HF_OFFLINE_ENV} is {env.get(HF_OFFLINE_ENV)!r}, not '1' (Code's form of the offline load "
                     f"the seat's step-10 read, Q5, rules for every later Qwen stage of Q-F0)")
    ms = env.get("MLXLM_USE_MODELSCOPE", "False")
    if str(ms).lower() == "true":
        probs.append(f"MLXLM_USE_MODELSCOPE is {ms!r} (mlx_lm tests .lower() == 'true'): mlx_lm would load "
                     f"through modelscope, not the hub cache")
    model_id = QWEN_MODEL_ID if model_id is None else str(model_id)
    here = Path.cwd() if cwd is None else Path(cwd)
    if (here / model_id).exists() or (here / model_id).is_symlink():
        probs.append(f"{here / model_id} exists or is a link: mlx_lm loads a local path named like the model id "
                     f"before the hub cache (a dangling link refused conservatively)")
    if cache_dir is None:
        from huggingface_hub import constants as hf_constants
        cache_dir = hf_constants.HF_HUB_CACHE
    repo = Path(cache_dir) / ("models--" + model_id.replace("/", "--"))
    try:
        rev = (repo / "refs" / "main").read_text(encoding="utf-8")
    except (OSError, ValueError):
        return probs + [f"no readable refs/main for {model_id} under {cache_dir}"], None
    if not re.fullmatch(r"[0-9a-f]{40}", rev):
        return probs + [f"refs/main for {model_id} is not, as raw text, a 40-hex revision: {rev[:60]!r} (the "
                        f"hub's offline load reads it raw)"], None
    snap = repo / "snapshots" / rev
    if not snap.is_dir():
        return probs + [f"refs/main names {rev}, but no snapshot directory {snap} exists"], None
    try:
        n_snap = sum(1 for d in (repo / "snapshots").iterdir() if d.is_dir())
        index = json.loads((snap / "model.safetensors.index.json").read_text(encoding="utf-8"))
        weights = sorted(set(index["weight_map"].values()))
        bad = [w for w in weights if type(w) is not str or not w or "/" in w or "\\" in w or w in (".", "..")]
    except (OSError, ValueError, KeyError, TypeError, AttributeError) as e:
        return probs + [f"snapshot {rev}: model.safetensors.index.json unreadable "
                        f"({type(e).__name__})"], None
    if bad:
        return probs + [f"snapshot {rev}: the index names a weight that is not a plain file name: {bad[:2]!r}"], None
    need = ["config.json", "tokenizer.json", "model.safetensors.index.json"] + weights
    missing = [f for f in need if not (snap / f).is_file()]
    if missing:
        probs.append(f"snapshot {rev} is incomplete: {missing[:4]} missing (an offline load would fail)")
    if not weights:
        probs.append(f"snapshot {rev}: the index names no weight file")
    try:
        from huggingface_hub import snapshot_download
        got = snapshot_download(model_id, local_files_only=True, allow_patterns=list(MLX_LM_ALLOW_PATTERNS),
                                cache_dir=str(cache_dir))
        if Path(got).resolve() != snap.resolve():
            probs.append(f"the hub's offline resolution gives {got}, not refs/main's snapshot {snap}")
    except Exception as e:                                      # noqa: BLE001 -- any failure refuses
        probs.append(f"the hub's offline resolution with mlx_lm's patterns refuses: {type(e).__name__}")
    info = {"model_id": model_id, "revision": rev, "snapshot_dir": str(snap),
            "n_snapshots": n_snap, "offline": env.get(HF_OFFLINE_ENV)}
    return probs, (None if probs else info)


def snapshot_line(info: dict) -> str:
    return (f"SNAPSHOT {info['model_id']} {info['revision']}: refs/main; {info['snapshot_dir']}; "
            f"{info['n_snapshots']} snapshot(s) in the model's cache repo; {HF_OFFLINE_ENV}={info['offline']}")


def _campaign_state(cpath: Path) -> tuple[str, dict]:
    """(state, summary) of the campaign checkpoint at ``cpath``, read tolerantly as JSON (no state check,
    so no total is computed or printed). state: "absent"; "unreadable" -- not a regular file (a FIFO is
    never opened: round 3's O3-3), not a JSON object, nested past the recursion limit, its sessions,
    campaign block, pauses or recorded PI stop mistyped, a pause lacking kind, at_launches or
    adjudication or carrying a value no write of the package gives it (a kind other than look, end_look
    and schedule_exhausted, a launch count that is not an int, an adjudication that is not a text, an arm
    other than A0 and A0s: round 3's ops refuter), a recorded text that cannot be encoded (the PI stop
    or any pause's adjudication, a lone surrogate: round 3's O3-4, round 4's F4-6), or a path whose stat
    fails (round 4's O4-3); "pending"
    (an end pending); "ended" (resume.ended_status); or "open". summary, the only thing the mirror and the
    RULING line read (round 2's B2-1: the checkpoint never leaves this function), free of any recorded
    text (round 3's B3-5): {"launched": a session is recorded, "pi_stop_sha256": the recorded PI stop's
    sha256 or None, "last": None or the last pause's {"kind", "at_launches", "arm", "adjudicated",
    "adjudication_sha16"} -- the digest the report gives a pause}; {} when unreadable."""
    from valence_core.m import resume, stages
    p = Path(cpath)
    try:
        if not (p.exists() or p.is_symlink()):
            return "absent", {"launched": False, "pi_stop_sha256": None, "last": None}
        if not p.is_file():
            return "unreadable", {}
    except OSError:
        return "unreadable", {}
    try:
        ck = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, ValueError, RecursionError):
        return "unreadable", {}
    camp = ck.get("campaign") if isinstance(ck, dict) else None
    camp = {} if camp is None else camp
    pauses = camp.get("pauses", []) if isinstance(camp, dict) else None
    if (not isinstance(ck, dict) or type(ck.get("sessions", [])) is not list or not isinstance(camp, dict)
            or type(pauses) is not list
            or not all(isinstance(x, dict) and {"kind", "at_launches", "adjudication"} <= set(x)
                       and x["kind"] in ("look", "end_look", "schedule_exhausted") and type(x["at_launches"]) is int
                       and (x["adjudication"] is None or type(x["adjudication"]) is str)
                       and x.get("arm") in (None, "A0", "A0s") for x in pauses)
            or not (camp.get("pi_stop") is None or type(camp.get("pi_stop")) is str)):
        return "unreadable", {}
    last = pauses[-1] if pauses else None
    try:
        for x in pauses:
            if x["adjudication"] is not None:
                x["adjudication"].encode("utf-8")
        summary = {"launched": bool(ck.get("sessions")),
                   "pi_stop_sha256": (None if camp.get("pi_stop") is None
                                      else hashlib.sha256(camp["pi_stop"].encode("utf-8")).hexdigest()),
                   "last": None if last is None else {
                       "kind": last["kind"], "at_launches": last["at_launches"], "arm": last.get("arm"),
                       "adjudicated": last["adjudication"] is not None,
                       "adjudication_sha16": (stages._sha16_text(last["adjudication"])
                                              if type(last["adjudication"]) is str else None)}}
    except UnicodeEncodeError:
        return "unreadable", {}
    if resume.pending_end(ck) is not None:
        return "pending", summary
    if resume.ended_status(ck) is not None:
        return "ended", summary
    return "open", summary


def campaign_ruling_problems(cpath: Path, adjudication: str | None, pi_stop: str | None) -> list[str]:
    """The refusals stages.run_campaign makes, after the load and before its first write, of a ruling
    that does not fit the campaign's state -- made here before the load, from ``_campaign_state``'s
    summary; [] when none applies.

    PIN (Code, declared at the campaign wiring; round 1's O1-1 and its refuter's mirror table): mirrors
    run_campaign's order (stages.py:2094-2131) over the states the stage writes: a PI stop text other than
    the one the checkpoint records (CHECKPOINT MISMATCH, made even beside an end pending); then, on a
    checkpoint neither pending nor ended (a pending end re-finishes at any invocation; an ended one is
    refused as ended): a PI stop with no session launched (PI STOP REFUSED); an adjudication on an
    exhausted schedule's unadjudicated pause with no PI stop (SCHEDULE EXHAUSTED); an adjudication with no
    unadjudicated pause (NO PAUSE TO ADJUDICATE). Each message is the stage's own words (round 2's B2-1),
    two with a declared suffix: CHECKPOINT MISMATCH's that the stage makes it after the load, and NO PAUSE
    TO ADJUDICATE's, where the last pause already carries a ruling, naming that pause and its ruling's
    sha16 and how the run resumes: with --resume alone, or, where this run also offers the PI's stop,
    with --resume and the PI's stop alone (round 2's O2-4; round 3's O3-2). The recorded PI stop is
    compared by its sha256 (the summary carries no text: round 3's B3-5). An invocation offering no
    ruling reads nothing (round 3's O3-3). An absent checkpoint is a campaign with no session and no
    pause. An unreadable or malformed one (``_campaign_state``'s "unreadable"; a state no write of the
    package makes) is not refused here: stage_precheck refuses it before the load (round 3's R-M3). The
    stage, which has no such screen, refuses it with a refusal of its own (CHECKPOINT UNREADABLE,
    CHECKPOINT STATE INCONSISTENT, CHECKPOINT MISMATCH and NO PAUSE TO ADJUDICATE among them), raises (a
    traceback, exit 1, at times after a write), or reads it as it stands -- a mistyped recorded PI stop
    beside the seat's adjudication alone, for one, is taken as the campaign's stop and the invocation ends
    PI-STOP on it, and an empty pauses block that is not a list ({}, "", 0) reads as no pause (round 2's
    O2-2; round 3's F3-1 and its refuter's RF3-1, O3-5; round 4's F4-2) -- which the self-test's stub
    path, where no precheck runs, shows."""
    if adjudication is None and pi_stop is None:
        return []
    state, sm = _campaign_state(cpath)
    if state in ("unreadable", "ended"):
        return []
    rec_pi = sm["pi_stop_sha256"]
    if (pi_stop is not None and rec_pi is not None
            and hashlib.sha256(pi_stop.strip().encode("utf-8")).hexdigest() != rec_pi):
        return [f"CHECKPOINT MISMATCH: {cpath} records the PI's stop; this run offers a different text -- "
                f"refusing (the stage makes this refusal after the load)"]
    if state == "pending":
        return []
    pi = pi_stop is not None or rec_pi is not None
    if pi and not sm["launched"]:
        return [f"PI STOP REFUSED at {cpath}: no session has launched -- a unit that never launches is "
                f"NOT-RUN by its Clock (m:192), not PI-stopped"]
    last = sm["last"]
    open_pause = last is not None and not last["adjudicated"]
    if open_pause and last["kind"] == "schedule_exhausted" and not pi and adjudication is not None:
        return [f"SCHEDULE EXHAUSTED at {cpath}: {last['arm']} has no committed cell left below its floor; "
                f"only the PI's stop (pi_stop) ends this campaign (m:192, m:247)"]
    if adjudication is not None and not open_pause:
        how = ("drop --adjudication-file: resume with --resume and the PI's stop alone" if pi_stop is not None
               else "resume with --resume alone")
        tail = ("" if last is None else
                f" -- its last pause ({last['kind']}, at {last['at_launches']} launches) already carries a ruling "
                f"(sha16 {last['adjudication_sha16']}); {how}")
        return [f"NO PAUSE TO ADJUDICATE at {cpath}: the campaign is not paused{tail}"]
    return []


def ruling_line(name: str, cpath: Path, rulings: dict) -> str | None:
    """The RULING line a campaign invocation offering a ruling prints before the load (round 1's O1-3):
    pick-free -- each text's sha16, of the stripped text (the report gives a pause's adjudication the same
    digest; the PI's stop's, where the stage records it only as the campaign's stop, and a ruling offered
    beside an end pending that the checkpoint does not record, which the stage does not apply there (NOT
    APPLIED), stand here alone: round 2's B2-3, round 3's F3-7, round 4's RM4-1), and the pause it is
    offered for (its kind and launch count, as the shown pause's line prints them) or the checkpoint's
    state, from ``_campaign_state``'s summary; None when no ruling is offered."""
    from valence_core.m import stages
    parts = [f"{who} (sha16 {stages._sha16_text(rulings[k].strip())})"
             for k, who in (("adjudication", "the seat's adjudication"), ("pi_stop", "the PI's stop"))
             if rulings.get(k) is not None]
    if not parts:
        return None
    state, sm = _campaign_state(cpath)
    last = sm.get("last") if state == "open" else None
    if last is not None and not last["adjudicated"]:
        where = f"for the pause at {last['at_launches']} launches ({last['kind']})"
    else:
        where = {"absent": "with no checkpoint on disk", "pending": "beside an end pending",
                 "ended": "on an ended campaign", "unreadable": "on an unreadable checkpoint"}.get(
            state, "with no pause unadjudicated")
    return f"RULING {name}: {' and '.join(parts)} offered {where}"


def stage_precheck(stage: str, extra: dict, *, resume_run: bool, out_root: Path,
                   rulings: dict | None = None) -> list[str]:
    """Refusals of a driver stage's start that need no model, made before the Qwen load; [] =
    none fired. The stage (stages.run_gate_stage / run_gid_pair) makes each of them again after
    the load, except two that only this precheck makes: on Python 3.13+, a looping link at the
    checkpoint path (see the comment below); and, on every version, a link at the G-ID artifact
    path that does not resolve, dangling or looping (the stage tests exists() alone).

    PIN (Code, declared at LOCK v0.2): the licence by file ((a)-(f)); the run-time known
    answers on the proposal the identity names; the renders of record; the committed schedule
    files; the checkpoint (the path itself; an ENDED one; one on disk without --resume and no
    end pending); at G-ID-F0m, the prior stage (G-TIME-F0's checkpoint at this out root, as
    stages.prior_gate reads it, a stub-written one refused) and an existing G-ID artifact (unless
    this stage's own checkpoint carries an end pending); m:267's laptop checklist (power, one
    model process, disk); the gate line and its files (CLAUDE.md and the analyzer committed,
    working tree identical; HEAD known). The failing checks' problems are returned together, one
    or more per check; ``_run_stage`` adds the driver check's and the snapshot check's and
    refuses once. NOT made here, so made only by the stage after the load, though several need
    no model: a resume's or a re-finish's comparison of the checkpoint with this run
    (resume.load_or_init's identity and readability refusals, stages._record_licence, _pend's
    END PENDING MISMATCH, G-ID's artifact identity on a re-finish); qwen_startup's pins (the
    audit artifact's, the frozen ban-list file's and the termination file's sha pins, and the
    ban list's rebuild against the live tokenizer); the counts against the committed files' n;
    the bars' firing-case completeness; and the stage's internal assertions. A SystemExit among
    them is reported by ``_run_stage`` as "STOP: <message>" with exit 4; a ValueError or
    AssertionError is uncaught (a traceback, exit 1).

    PIN (Code, declared at the campaign wiring): the stage that makes them again is also
    stages.run_campaign. At G-F0m-Qwen the prior gate also requires G-ID-F0m's artifact (the
    comment at the prior gate below). At the campaign: its committed campaign schedule files; the
    prior stage, G-F0m-Qwen's checkpoint at this out root ended PASS (prior_gate, PRIOR_STAGE);
    G-ID-F0m's artifact if on disk (stages.gid_artifact_problems, as run_campaign re-checks it); a
    paused campaign offered no ruling (``rulings`` None, or both texts None) not refused as
    existing; and a ruling's fit to the campaign's state (``campaign_ruling_problems``: NO PAUSE TO
    ADJUDICATE, PI STOP REFUSED, SCHEDULE EXHAUSTED, a PI stop text other than the one recorded),
    the stage making each again after the load; and a campaign checkpoint path that exists and that the
    driver cannot read as a campaign checkpoint (``_campaign_state``'s "unreadable": not a regular file --
    a FIFO, a device, a directory -- not a JSON object, nested past the recursion limit, a shape or value
    no write of the package makes, a recorded text that cannot be encoded), which only this precheck
    makes, beside the two the opening names: without --resume the stage refuses it as existing, and with
    --resume, having no such screen, it opens it after the load -- it blocks on a FIFO's read, refuses a
    directory or a file that is not a JSON object (CHECKPOINT UNREADABLE), raises, or reads it as it
    stands (round 3's O3-3, O3-4 and their refuter's R-M3; round 4's F4-5). Not made here:
    the path the G-ID licence gives on
    the loaded backend (PATH MISMATCH); the floors and the launch-count projection a checkpoint
    records; and NOT APPLIED -- the seat's adjudication, or a PI stop the checkpoint does not
    record, offered beside an end pending: the stage re-finishes that end and then refuses (exit 4);
    a PI stop equal to the recorded one re-finishes with no refusal, and a different one is CHECKPOINT
    MISMATCH, refused before any re-finish (and here). A pending end re-finishes at any invocation,
    so the precheck lets it through. Every problem returned passes through ``redact_totals`` (the step-14
    read's Q3), so a direct caller (the laptop's dry precheck) sees no totals either."""
    from valence_core.m import guard, resume, stages
    if stage not in DRIVER_STAGES:
        raise ValueError(f"stage_precheck: {stage!r} is not one of {DRIVER_STAGES}")
    name = stages.stage_name(TIME_UNIT, stage)
    probs = [f"licence: {p}" for p in stages.licence_problems(extra)]
    proposal = stages._proposal_path(extra)
    probs += [f"startup: {p}" for p in stages.startup_problems(proposal)]
    try:
        stages._renders_of_record(extra, name)
    except SystemExit as e:
        probs.append(f"renders: {e}")
    paths = stages.out_paths(TIME_UNIT, stage, out_root)
    wanted = {"time": [("time", t) for t, _ in TIME_COUNTS], "id": [("id", ID_TEMPLATE)],
              "qual": [("qual", t) for t, _ in QUAL_COUNTS],
              "campaign": [("campaign", t) for t, _ in CAMPAIGN_LAUNCH_COUNTS]}[stage]
    try:
        stages.load_committed(TIME_UNIT, wanted, paths["schedules"])
    except SystemExit as e:
        probs.append(f"schedules: {e}")
    cpath = None
    try:
        cpath = stages.checkpoint_path(None, paths)
        resume.refuse_ended(cpath)
        # is_symlink: checkpoint_path resolve()s non-strictly; on Python 3.13+ a looping link comes
        # back unresolved (a link on the loop; a dangling link resolves to its absent target on
        # every version), so the resolved path can still be a link, which only this precheck
        # refuses; on the venv's 3.12 resolve() raises RuntimeError on the loop (caught below)
        # PIN (Code, declared at the campaign wiring): a paused campaign re-invoked with neither the seat's
        # adjudication nor the PI's stop is shown its pause "with or without --resume" (stages.run_campaign's
        # finding-R6 PIN, stages.py:2067-2073, read by the same stages._paused_unadjudicated), so the precheck
        # does not refuse it as existing
        offered = rulings is not None and any(v is not None for v in rulings.values())
        # (round 4's F4-2: stages._paused_unadjudicated subscripts a pauses block it has not type-checked -- a
        # non-empty one that is not a list raises -- so it is asked only of a checkpoint the screen reads as open)
        shown = (stage == "campaign" and not offered and _campaign_state(cpath)[0] == "open"
                 and stages._paused_unadjudicated(cpath))
        if ((cpath.exists() or cpath.is_symlink()) and not resume_run and not resume.pending_at(cpath)
                and not shown):
            probs.append(f"checkpoint: CHECKPOINT EXISTS at {cpath}; pass --resume to continue it or "
                         f"move it aside (never overwritten)")
    except SystemExit as e:
        probs.append(f"checkpoint: {e}")
    except (RuntimeError, OSError) as e:
        probs.append(f"checkpoint: the checkpoint path does not resolve ({type(e).__name__})")
    # PIN (Code, declared at LOCK v1.0): G-F0m-Qwen's prior is G-TIME-F0 too (PRIOR_STAGE,
    # stages.py:644), and for the Qwen qualification prior_gate also requires G-ID-F0m's artifact,
    # of any verdict, admissible under this run's proposal (or one its lock re-adopts; none under
    # v0.2, v0.2 §0) and not written on the stub (stages.py:846-853); the precheck makes both
    # refusals before the load (the prior one as at G-ID-F0m).
    # PIN (Code, declared at the campaign wiring): the campaign's prior is G-F0m-Qwen (PRIOR_STAGE), its
    # checkpoint at this out root ended PASS (prior_gate, m:283, m:302); and the campaign re-checks G-ID-F0m's
    # artifact on disk as the qualification checked it (stages.run_campaign's finding-R3 PIN,
    # stages.py:2053-2062: under this run's proposal, not written on the stub; absent gives the uncached path
    # and has nothing to check). The precheck makes both refusals before the load; the stage makes them again.
    if stage in ("id", "qual", "campaign"):
        prior = stages.out_paths(TIME_UNIT, stages.PRIOR_STAGE[stage], out_root)["ckpt"]
        try:
            stages.prior_gate(TIME_UNIT, stage, prior, proposal_sha256=extra["proposal_sha256"],
                              prior_proposal_sha256s=extra.get("prior_proposal_sha256s") or [],
                              require_real=True)
        except SystemExit as e:
            probs.append(f"prior: {e}")
    if stage == "campaign" and cpath is not None:
        try:
            exists_, regular_ = cpath.exists(), cpath.is_file()
        except OSError:                                     # reported by the checkpoint block (round 4's O4-3)
            exists_ = regular_ = False
        if exists_ and not regular_:
            probs.append(f"checkpoint: {cpath} exists and is not a regular file (refused before it is opened)")
        elif exists_ and _campaign_state(cpath)[0] == "unreadable":
            probs.append(f"checkpoint: {cpath} cannot be read as a campaign checkpoint (not a JSON object, or a "
                         f"shape or value no write of the package makes) -- refused before the load; a checkpoint "
                         f"is never edited by hand")
    if stage == "campaign" and cpath is not None and rulings is not None:
        probs += [f"ruling: {p}" for p in campaign_ruling_problems(cpath, rulings.get("adjudication"),
                                                                   rulings.get("pi_stop"))]
    if stage == "campaign":
        probs += [f"artifact: {p}" for p in stages.gid_artifact_problems(
            TIME_UNIT, accepted=stages.accepted_proposals(extra["proposal_sha256"],
                                                          extra.get("prior_proposal_sha256s") or []),
            require_real=True)]
    if stage == "id":
        gid_path = guard.gid_artifact_path(TIME_UNIT)
        pending = cpath is not None and resume.pending_at(cpath)
        if (gid_path.exists() or gid_path.is_symlink()) and not pending:
            probs.append(f"artifact: G-ID ARTIFACT EXISTS at {gid_path}; it is never overwritten")
    probs += [f"preflight: {p}" for p in guard.preflight_laptop()]
    probs += [f"gate line: {p}" for p in stages.gate_line(name, proposal)[1]]
    for what, path in (("CLAUDE.md", stages.CLAUDE_MD_PATH), ("analyzer", stages.ANALYZER_PATH)):
        rel = stages._repo_rel(path)
        probs += ([f"gate line: {what} {path} lies outside the repository"] if rel is None
                  else [f"gate line: {what} {x}" for x in stages._committed(rel)[0]])
    return [redact_totals(p) for p in probs]


def time_precheck(extra: dict, *, resume_run: bool, out_root: Path) -> list[str]:
    """G-TIME-F0's pre-load refusals (``stage_precheck`` for "time")."""
    return stage_precheck("time", extra, resume_run=resume_run, out_root=out_root)


def ruling_texts(adjudication_file: str | None, pi_stop_file: str | None) -> tuple[dict, list[str]]:
    """({"adjudication": text or None, "pi_stop": text or None}, problems) of the campaign's two
    ruling files.

    PIN (Code, declared at the campaign wiring): stages.run_campaign takes the seat's adjudication
    of a pending pause and the PI's stop as texts, recorded in the checkpoint only ("the seat's (or
    the PI's) text stays in the checkpoint only -- it may name anything, a pair label included",
    stages.py:1989-1991); the driver takes each as a file named on the command line, so the text
    stands in no command line, launch line or raw, and prints neither (its path does stand in the
    INVOCATION line, so the file is named for nothing it says). A file given must be a regular file
    (a FIFO or a device is refused before it is opened), UTF-8 (a leading byte-order mark is
    dropped: utf-8-sig) and not blank -- a text with no visible character (round 1's O1-5: only
    whitespace, format characters such as a zero-width space, or control characters); its text is
    passed as read (the stage strips it)."""
    import unicodedata
    texts: dict = {"adjudication": None, "pi_stop": None}
    probs: list[str] = []
    for key, flag, given in (("adjudication", "--adjudication-file", adjudication_file),
                             ("pi_stop", "--pi-stop-file", pi_stop_file)):
        if given is None:
            continue
        try:
            if not Path(given).is_file():
                probs.append(f"{flag} {given}: not a regular file")
                continue
            txt = Path(given).read_bytes().decode("utf-8-sig")
        except (OSError, ValueError) as e:
            probs.append(f"{flag} {given}: unreadable as UTF-8 text ({type(e).__name__})")
            continue
        if not any(not c.isspace() and unicodedata.category(c)[0] not in "CZ" for c in txt):
            probs.append(f"{flag} {given}: blank (a ruling is a text with a visible character)")
            continue
        texts[key] = txt
    return texts, probs


def _run_stage(stage: str, unit: str, *, proposal_file: str | None, lock_file: str | None,
               analyzer_sha256: str | None, package_sha256: str | None, renders_sha16: str | None,
               resume_run: bool, adapter_factory=None, out_root: Path | None = None,
               adjudication_file: str | None = None, pi_stop_file: str | None = None) -> int:
    """G-TIME-F0 (m:280) and G-F0m-Qwen (m:283) through stages.run_gate_stage, G-ID-F0m
    (m:281) through stages.run_gid_pair, or the Q-F0 campaign (m:358 step 16) through
    stages.run_campaign. Exit: stages.EXIT_CODES for the stage's status -- 0 PASS (at the
    campaign COMPLETE, CAP and PI-STOP); 3 PAUSE; at G-ID 5 FAIL and 6 NOT-DETERMINED -- and 4 STOP
    (the stage's; any SystemExit from the loader or the
    stage, qwen_or_explain's included, as gcal's PIN maps it; or the driver's own post-load
    snapshot re-read or model-id check -- each "STOP: " and its message);
    2 refused before the load (nothing loaded or written); any other exception is uncaught (a
    traceback; exit 1, or killed by SIGINT on Ctrl-C, which a shell reports as 130). Every
    REFUSED and STOP line is printed through ``_say`` (redact_totals, the step-14 read's Q3).

    PIN (Code, declared at LOCK v0.2): ``adapter_factory`` and ``out_root`` are the selftest's
    seam (a scripted stub writing a test directory, which stages refuses anywhere under
    data/m); without the factory the adapter is Qwen through qwen_or_explain, the out root is
    stages.DEFAULT_OUT (read at call time), a given ``out_root`` is refused before any load,
    and stage_precheck, the driver check (one driver_problems call) and the snapshot check (one
    qwen_snapshot call), their problems refused together, then the DRIVER and SNAPSHOT lines,
    come before the load; after it, the snapshot is read again and the adapter's model_id
    compared: a re-read that refuses, a moved refs/main or another model id STOPs before a
    session (SNAPSHOT RE-READ REFUSED / SNAPSHOT MOVED / MODEL ID). G-ID-F0m's prior is
    G-TIME-F0's checkpoint at the same out root. A STOP, and any exit other than 0 or 2, is
    escalated to the seat; Code never self-adjudicates.

    PIN (Code, declared at the campaign wiring): the campaign's prior is G-F0m-Qwen's checkpoint
    at the same out root; its launch counts and hour cap are this driver's declared values, whose
    line forms the lock's text carries (stage_identity_extra), and its floors the package's
    (``campaign_floors``: schedule.FLOORS under the locked path);
    ``adjudication_file`` / ``pi_stop_file`` (``ruling_texts``, refused before the precheck when
    not a regular file, not UTF-8 or blank) are the campaign's alone, and their fit to the
    campaign's state is refused before the load (``campaign_ruling_problems``, in the precheck).
    A campaign PAUSE (exit 3) is escalated: a look's pause resumes only with --resume and the seat's
    adjudication, or ends by the PI's stop (with --resume); an exhausted schedule's ends only by the
    PI's stop; an end look's pause beside a terminal end is never resumed, its ruling entering
    VERDICTS as the analyzer's declared --adjudication file (the seat's C9(i)). A STOP naming NOT
    APPLIED is the stage declining a ruling offered beside an end pending, after re-finishing that
    end (stages.py:2503-2520); an adjudication offered there is never offered again, whatever the
    message's "offer it again" says (it holds for the PI's stop alone): a re-finished pause that
    leaves the campaign open is then shown and takes the seat's own ruling on it (a look's; an
    exhausted schedule's only beside the PI's stop) or the PI's stop again, and an end that leaves
    the campaign ended stands, its routes being VERDICTS', as its message says; the NOT APPLIED line
    is not itself a stage's STOP -- where the end it re-finished is a STOP (announced before it),
    that STOP is escalated as any STOP."""
    if stage not in DRIVER_STAGES:
        raise ValueError(f"_run_stage: {stage!r} is not one of {DRIVER_STAGES}")
    if stage != "campaign" and (adjudication_file is not None or pi_stop_file is not None):
        raise ValueError(f"_run_stage: {stage!r} takes no adjudication or PI-stop file (the campaign's alone)")
    if unit != TIME_UNIT:
        print(refusal(stage, unit), file=sys.stderr, flush=True)
        return 2
    given = {"proposal_file": proposal_file, "lock_file": lock_file, "analyzer_sha256": analyzer_sha256,
             "package_sha256": package_sha256, "renders_sha16": renders_sha16}
    missing = ["--" + k.replace("_", "-") for k in TIME_FLAGS if given[k] is None]
    if missing:
        _say(f"REFUSED: {stage} --unit {TIME_UNIT} needs {missing}: the lock's values (lock §0, \"How a "
             f"stage cites this file\"); nothing loaded")
        return 2
    if out_root is not None and adapter_factory is None:
        _say(f"REFUSED: {stage}: an out root names a test directory; the Qwen run writes data/m only "
             f"(nothing loaded)")
        return 2
    from valence_core.m import stages
    name = stages.stage_name(TIME_UNIT, stage)
    extra, probs = stage_identity_extra(stage, proposal_file, lock_file, analyzer_sha256=analyzer_sha256,
                                        package_sha256=package_sha256, renders_sha16=renders_sha16)
    if probs:
        _say(f"REFUSED: {name}: {probs}; nothing loaded")
        return 2
    rulings, rprobs = ruling_texts(adjudication_file, pi_stop_file)
    if rprobs:
        _say(f"REFUSED: {name}: {rprobs}; nothing loaded")
        return 2
    root = Path(stages.DEFAULT_OUT if out_root is None else out_root)
    try:
        # PIN (Code, declared at the campaign wiring; round 1's O1-3): a campaign invocation offering a ruling
        # prints, before the load (on the Qwen path after the precheck), the RULING line (ruling_line: the
        # texts' sha16 and the pause they are offered for)
        def say_ruling() -> None:
            if stage == "campaign":
                rline = ruling_line(name, stages.checkpoint_path(None, stages.out_paths(TIME_UNIT, stage, root)),
                                    rulings)
                if rline is not None:
                    print(rline, flush=True)
        if adapter_factory is None:
            pre = stage_precheck(stage, extra, resume_run=resume_run, out_root=root, rulings=rulings)
            dprobs, dsha = driver_problems()
            sprobs, snap = qwen_snapshot()
            # PIN (Code, declared at LOCK v1.0): the step-14 refusal (the seat's G-ID-F0m
            # adjudication, Q3): at a stage in REVISION_STAGES a refs/main other than QWEN_REVISION is
            # refused here, with the other pre-load problems; after the load the re-read's SNAPSHOT
            # MOVED covers the revision then read (it STOPs on any change from this read).
            if stage in REVISION_STAGES and snap is not None and snap["revision"] != QWEN_REVISION:
                sprobs = list(sprobs) + [f"refs/main is {snap['revision']}, not the revision of record "
                                         f"{QWEN_REVISION} (LOCK-m-F0 v0.2 §4)"]
            pre += [f"driver: {p}" for p in dprobs] + [f"snapshot: {p}" for p in sprobs]
            if pre:
                _say(f"REFUSED: {name}: {pre}; nothing loaded")
                return 2
            print(f"DRIVER {DRIVER_REL} {dsha}: committed at HEAD {stages._git_head()}, working tree "
                  f"identical", flush=True)
            print(snapshot_line(snap), flush=True)
            say_ruling()
            adapter = _load_qwen()
            # the snapshot re-read after the load (Code's): a re-read that refuses, a moved refs/main
            # or another model id STOPs before any session (a SystemExit, exit 4 below). It narrows,
            # not closes, the window between the precheck's read and the load's: a move and back
            # between the two reads is not seen
            sprobs2, snap2 = qwen_snapshot()
            if sprobs2 or snap2 is None:
                raise SystemExit(f"SNAPSHOT RE-READ REFUSED ({name}): after the load the snapshot check refuses: "
                                 f"{sprobs2} -- no session runs")
            if snap2["revision"] != snap["revision"]:
                raise SystemExit(f"SNAPSHOT MOVED ({name}): before the load {snap['revision']}; after it "
                                 f"{snap2['revision']} -- no session runs")
            if getattr(adapter, "model_id", None) != snap["model_id"]:
                raise SystemExit(f"MODEL ID ({name}): the adapter loaded {getattr(adapter, 'model_id', None)!r}, "
                                 f"the snapshot check read {snap['model_id']!r} -- no session runs")
            print(f"SNAPSHOT re-read after the load: unchanged ({snap['revision']}); adapter model_id "
                  f"{snap['model_id']}", flush=True)
        else:
            say_ruling()
            adapter = adapter_factory()
        if stage == "time":
            res = stages.run_gate_stage(adapter, unit=TIME_UNIT, gate="time",
                                        templates_counts=list(TIME_COUNTS), resume=resume_run,
                                        identity_extra=extra, substrate="qwen", out_root=root)
        elif stage == "qual":
            # PIN (Code, declared at LOCK v1.0): G-F0m-Qwen's prior is G-TIME-F0's checkpoint at this
            # run's out root, as G-ID-F0m's is; on the Qwen path that root is stages.DEFAULT_OUT (an out
            # root given without a factory is refused above). The stage's prior_gate reads it again after
            # the load, with G-ID-F0m's artifact (the precheck's refusals, declared there, made again).
            res = stages.run_gate_stage(adapter, unit=TIME_UNIT, gate="qual",
                                        templates_counts=list(QUAL_COUNTS), resume=resume_run,
                                        identity_extra=extra, substrate="qwen", out_root=root,
                                        prior_ckpt=stages.out_paths(TIME_UNIT, "time", root)["ckpt"])
        elif stage == "campaign":
            # PIN (Code, declared at the campaign wiring): the campaign's prior is G-F0m-Qwen's checkpoint at
            # this run's out root (PRIOR_STAGE), as the precheck read it; the stage reads it again after the
            # load (prior_gate), with G-ID-F0m's artifact (the precheck's refusals, declared there, made again)
            res = stages.run_campaign(adapter, unit=TIME_UNIT, floors=campaign_floors(),
                                      launch_counts=dict(CAMPAIGN_LAUNCH_COUNTS), hour_cap=CAMPAIGN_HOUR_CAP,
                                      prior_ckpt=stages.out_paths(TIME_UNIT, "qual", root)["ckpt"],
                                      resume=resume_run, identity_extra=extra, substrate="qwen", out_root=root,
                                      adjudication=rulings["adjudication"], pi_stop=rulings["pi_stop"])
        else:
            res = stages.run_gid_pair(adapter, unit=TIME_UNIT, template=ID_TEMPLATE, resume=resume_run,
                                      identity_extra=extra,
                                      prior_ckpt=stages.out_paths(TIME_UNIT, "time", root)["ckpt"],
                                      out_root=root)
    except SystemExit as e:
        _say(f"STOP: {e}")
        return 4
    return stages.EXIT_CODES[res["status"]]


def run_time(unit: str, **kw) -> int:
    """G-TIME-F0 (§8 step 10, m:280): ``_run_stage`` for "time"."""
    return _run_stage("time", unit, **kw)


def run_id(unit: str, **kw) -> int:
    """G-ID-F0m (§8 step 12, m:281): ``_run_stage`` for "id"."""
    return _run_stage("id", unit, **kw)


def run_qual(unit: str, **kw) -> int:
    """G-F0m-Qwen (§8 step 14, m:283): ``_run_stage`` for "qual"."""
    return _run_stage("qual", unit, **kw)


def run_campaign(unit: str, **kw) -> int:
    """The Q-F0 campaign (§8 step 16, m:358): ``_run_stage`` for "campaign"."""
    return _run_stage("campaign", unit, **kw)


# --- self-test ---------------------------------------------------------------------------
def _short(x, n: int = 160) -> str:
    s = x if isinstance(x, str) else repr(x)
    s = " ".join(s.split())
    return s if len(s) <= n else s[:n - 3] + "..."


def _forbidden() -> tuple[str, ...]:
    # built, never written whole: a site-check suite greps the repo for these literals
    return ("choice_read_" + "state" + "present", "(10)" + " the", "slip" + " (10)")


def _forbidden_hits(paths) -> list[str]:
    hits = []
    for p in paths:
        txt = Path(p).read_text(encoding="utf-8")
        hits += [f"{Path(p).name}: {f!r}" for f in _forbidden() if f in txt]
    return hits


def _m_sources() -> list[Path]:
    return sorted((REPO / "valence_core" / "m").glob("*.py")) + [Path(__file__).resolve()]


def _selftest(chk) -> None:
    """The driver's integration checks: stages on the scripted stub, in a temp dir."""
    from valence_core.m import (corr, guard, keys, resume, runner_olmo, runner_qwen, scaffold, schedule,
                                stages, testing)

    roster_rx = re.compile(r"\b(?:" + "|".join(map(re.escape, corr.ALL_ROSTER_WORDS)) + r")\b", re.I)
    menu_frags = ("| choice]", "Available configs", "Configs available", "Options:",
                  "Configs on offer", "Config choice")

    def stdout_problems(text: str) -> list[str]:
        probs = ["roster label"] if roster_rx.search(text) else []
        probs += [f"menu text {f!r}" for f in menu_frags if f in text]
        probs += ["pick line" for ln in text.splitlines()
                  if ln.strip().lower() in corr.ALL_ROSTER_WORDS]
        return probs

    outs: list[str] = []
    rsha = corr.renders_sha(scaffold.pool_and_renders()[1])

    def xtra(lp: str | None = "uncached", **over) -> dict:
        # selftest identity_extra: fake 64-hex lock and proposal hashes (never "pre-lock"),
        # the renders of record's sha16, and the locked path (none at G-ID)
        d = {"lock_sha256": "1" * 64, "proposal_sha256": "2" * 64, "renders_sha16": rsha}
        if lp is not None:
            d["locked_path"] = lp
        d.update(over)
        return d

    errs: list[str] = []

    def capture(fn, *a, **kw):
        # stdout to outs; stderr to errs beside it, then passed on unchanged to the caller's stderr (which a
        # check may have redirected to its own buffer)
        buf, ebuf = io.StringIO(), io.StringIO()
        res = exc = None
        import warnings
        try:
            with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(ebuf), warnings.catch_warnings():
                # the repo's own unclosed-file ResourceWarnings (shown under PYTHONWARNINGS=always or -X dev) kept
                # out of the captured stderr, whose line forms a check declares (round 2's C2-5 (b))
                warnings.simplefilter("ignore", ResourceWarning)
                try:
                    res = fn(*a, **kw)
                except (SystemExit, stages._Interrupt) as e:      # noqa: SLF001 (selftest helper)
                    exc = e
        finally:
            sys.stderr.write(ebuf.getvalue())
        outs.append(buf.getvalue())
        errs.append(ebuf.getvalue())
        return res, exc, buf.getvalue()

    @contextlib.contextmanager
    def env_pod(value):
        had, prev = resume.POD_ENV in os.environ, os.environ.get(resume.POD_ENV)
        if value is None:
            os.environ.pop(resume.POD_ENV, None)
        else:
            os.environ[resume.POD_ENV] = value
        try:
            yield
        finally:
            if had:
                os.environ[resume.POD_ENV] = prev
            else:
                os.environ.pop(resume.POD_ENV, None)

    @contextlib.contextmanager
    def patched(obj, attr: str, value):
        saved = getattr(obj, attr)
        setattr(obj, attr, value)
        try:
            yield
        finally:
            setattr(obj, attr, saved)

    def gates_at(path: Path):
        return patched(guard, "GATES_DIR", path)

    @contextlib.contextmanager
    def olmo_stub_startup():
        # PIN (Code, declared at LOCK v0.1): olmo_startup refuses the stub by design (its
        # six ban ids cannot match b3's nine-id sha16), so the OLMo stage checks substitute
        # stages' reference to it with a setup built as runner_olmo's selftest builds one
        # (testing.olmo_kit), restored in finally. Production code has no seam.
        kit = testing.olmo_kit()
        setup = runner_olmo.OLMoSetup(audit=kit["audit"], ban_ids=kit["ban_ids"],
                                      ban_strings=kit["ban_strings"], term_rx=kit["term_rx"],
                                      audit_sha16=runner_olmo.olmo_audit_sha16())
        with patched(stages, "olmo_startup", lambda adapter, ckpt: setup):
            yield setup

    def cells_for(unit: str, stage: str, counts: dict) -> dict:
        r = schedule.roster_for(unit)
        out = {}
        for t, m in counts.items():
            cs = (schedule.campaign_schedule(unit, t, r, -(-m // schedule.UNIT_SIZE))[:m]
                  if stage == "campaign" else schedule.gate_schedule(unit, stage, t, r, m))
            out.update({(t, s): c for s, c in enumerate(cs)})
        return out

    def adapter_for(unit, stage, counts, rule=None, interrupt=None, picks=None):
        ad = testing.ScriptedAdapter() if unit == "Q-F0" else testing.OLMoScriptedAdapter()
        ad.load(stages._script_policy(unit, stage, cells_for(unit, stage, counts), rule, interrupt),
                picks)
        return ad

    menu_rx = re.compile(r"(?:Available configs|Configs available|Options|Configs on offer): "
                         r"([a-z]+), ([a-z]+)\nConfig choice \(one word\):")

    def first_label(low: bool):
        # a pick plan: every read picks its menu's first label, at high label mass or (low)
        # at low label mass (testing.LOW_MASS)
        def f(text):
            found = menu_rx.findall(text or "")
            return ((testing.LOW_MASS if low else "") + found[-1][0]) if found else None
        return f

    def cut_at_end(pred):
        # resume.write_checkpoint wrapped (selftest only, restored on exit): the first write
        # whose checkpoint satisfies pred dies, as a process killed between a stage's
        # outputs and its persisted end would
        real = resume.write_checkpoint
        state = {"cut": 0}

        def w(path, ck):
            if state["cut"] == 0 and pred(ck):
                state["cut"] += 1
                raise stages._Interrupt("selftest: killed before the end was persisted")
            real(path, ck)
        return patched(resume, "write_checkpoint", w)

    def has_end(ck) -> bool:
        return (ck.get("stage_end") is not None or bool(ck.get("stop"))
                or (ck.get("campaign") or {}).get("terminal") is not None)

    def adj_of(res) -> dict:
        return json.loads(Path(res["adjudication"]).read_text(encoding="utf-8"))

    def on_backend_y(ad):
        # a second backend: the same stub with one provenance field moved (selftest only)
        real = ad.provenance
        ad.provenance = lambda: {**real(), "platform": "selftest-backend-Y"}
        return ad

    def ckpt_of(res) -> dict:
        return json.loads(Path(res["checkpoint"]).read_text(encoding="utf-8"))

    def rep_of(res) -> dict:
        return json.loads(Path(res["report"]).read_text(encoding="utf-8"))

    def strip_secs(recs):
        return [{k: v for k, v in r.items() if k != "seconds"} for r in recs]

    def synthetic_prior(path: Path, unit: str, stage: str, status: str) -> Path:
        # a prior stage's checkpoint with a persisted end (resume's public API only)
        tpls = list(keys.templates(unit))
        ident = resume.Identity(unit=unit, stage=stage, template_set=tpls, lock_sha256="1" * 64,
                                schedule_sha256="3" * 64, path="uncached", hour_cap=None,
                                n={t: 1 for t in tpls}, audit_v2_sha16="4" * 16, ban_sha="5" * 16,
                                backend_identifier="6" * 16, proposal_sha256="2" * 64)
        path.parent.mkdir(parents=True, exist_ok=True)
        ck = resume.load_or_init(path, ident, False)
        ck["stage_end"] = {"status": status, "fired": [], "adjudication": None}
        resume.write_checkpoint(path, ck)
        return path

    QT = {"A0": 1, "A0s": 1}
    QQ = {"A0": 8, "A0s": 16}
    OT = {"A0-OLMo-sft": 1, "A0s-OLMo-sft": 1}
    OQ = {"A0-OLMo-sft": 8, "A0s-OLMo-sft": 16}

    with tempfile.TemporaryDirectory(prefix="m_selftest_") as td:
        base = resume.refuse_canonical_out(Path(td))

        def fresh(name: str) -> Path:
            root = resume.refuse_canonical_out(base / name / "m")
            schedule.write_schedule_files(root / "schedules")
            return root

        def gate(unit, g, counts, root, ad, *, lp="uncached", **kw):
            return capture(stages.run_gate_stage, ad, unit=unit, gate=g,
                           templates_counts=list(counts.items()),
                           identity_extra=kw.pop("identity_extra", xtra(lp)),
                           substrate="qwen" if unit == "Q-F0" else "olmo", out_root=root, **kw)

        def gid(root, ad, prior, **kw):
            return capture(stages.run_gid_pair, ad, unit="Q-F0", identity_extra=xtra(None),
                           prior_ckpt=prior, out_root=root, **kw)

        def tampered_runner(mutate, when):
            # stages' runner reference wrapped (selftest only, restored on exit) so a chosen
            # record leaves the runner with one field off; the REAL verifier must name it
            real = stages.run_session_qwen

            def tampered(adapter, sc, audit, ban_ids, *, path_cached, term_rx):
                rec = real(adapter, sc, audit, ban_ids, path_cached=path_cached, term_rx=term_rx)
                if when(sc, path_cached):
                    mutate(rec)
                return rec
            return patched(stages, "run_session_qwen", tampered)

        def bump_text(rec):
            rec["rounds"][0]["text"] += " x"

        def bump_seed(rec):
            rec["rounds"][0]["seed"] += 1

        with gates_at(base / "no-gates"):
            # --- G-TIME-F0: both sessions; the sham bar fires at 3, not at 2 --------------
            root = fresh("time_clean")
            res, exc, txt = gate("Q-F0", "time", QT, root, adapter_for("Q-F0", "time", QT))
            ck, rep = ckpt_of(res), rep_of(res)
            prior_time = res["checkpoint"]
            chk("m_sessions: G-TIME-F0 runs A0 then A0s uncached, verified; bar silent; PASS persisted as "
                "the checkpoint's stage_end; the STAGE line names the path",
                res["status"] == "PASS" and [r["template"] for r in ck["sessions"]] == ["A0", "A0s"]
                and all(r["verified"] and r["path"] == "uncached" for r in ck["sessions"])
                and rep["bars"][0]["name"] == "round_degeneracy@G-TIME-F0" and not rep["bars"][0]["fired"]
                and ck["stage_end"] == {"status": "PASS", "fired": [], "adjudication": None}
                and "STAGE G-TIME-F0 PASS path=uncached" in txt, res["status"])
            r3 = lambda t, s, n, c: "Config choice one." if t == "A0s" and n in (5, 7, 9) else None
            r2 = lambda t, s, n, c: "Config choice one." if t == "A0s" and n in (5, 7) else None
            res3, _, _ = gate("Q-F0", "time", QT, fresh("time_fire"), adapter_for("Q-F0", "time", QT, r3))
            res2, _, _ = gate("Q-F0", "time", QT, fresh("time_quiet"), adapter_for("Q-F0", "time", QT, r2))
            b3, b2 = rep_of(res3)["bars"][0], rep_of(res2)["bars"][0]
            prior_time_stop = res3["checkpoint"]
            chk("m_sessions: G-TIME-F0's sham bar fires at 3 v2 claims in 10 rounds (STOP) and is "
                "silent at 2 (PASS)",
                (res3["status"], b3["fired"], b3["k"], b3["n"], res2["status"], b2["fired"], b2["k"])
                == ("STOP", True, 3, 10, "PASS", False, 2), (b3["message"], b2["message"]))
            a3 = adj_of(res3)
            ev3 = a3["events"][0]
            ck3 = ckpt_of(res3)
            sham3 = [r for r in ck3["sessions"] if r["template"] == "A0s"][0]
            chk("m_sessions: a fired binomial bar writes the confined adjudication excerpt beside the "
                "checkpoint -- the numerator's 3 sham rounds (header bytes, generation, audit) and the 3 "
                "sham picks those free rounds reveal; a PASS writes none",
                ev3["kind"] == "bars" and ev3["event"] == "STOP"
                and ev3["bars"] == ["round_degeneracy@G-TIME-F0"]
                and [(x["template"], x["n"], x["generation"]) for x in ev3["rounds"]]
                == [("A0s", 5, "Config choice one."), ("A0s", 7, "Config choice one."),
                    ("A0s", 9, "Config choice one.")]
                and all(x["header"].startswith(f"[round {x['n']} ") and x["audit"]["claim"] == "v2"
                        for x in ev3["rounds"])
                and [(p["ci"], p["pick"]) for p in ev3["picks_revealed"]]
                == [(c["ci"], c["pick"]) for c in sham3["choices"] if c["ci"] in (0, 2, 4)]
                and Path(res3["adjudication"]).name == "Q-F0_time_adjudication.json"
                and rep_of(res3)["files"]["adjudication"] == "ckpt/Q-F0_time_adjudication.json"
                and res2["adjudication"] is None
                and not (Path(res2["checkpoint"]).parent / "Q-F0_time_adjudication.json").exists(),
                [(x["n"], x["generation"]) for x in ev3["rounds"]])

            # --- the contrast free-phase hair trigger ------------------------------------
            root = fresh("time_hair")
            rh = lambda t, s, n, c: "<|im_end|>" if t == "A0" and n == 6 else None
            res, exc, txt = gate("Q-F0", "time", QT, root, adapter_for("Q-F0", "time", QT, rh))
            ck, rep = ckpt_of(res), rep_of(res)
            chk("m_sessions: a contrast free-phase hair trigger STOPs the stage, announced by phase "
                "alone (no class on stdout or in the report; the class and the fired round -- free, "
                "n 6, ci 1 -- only in the checkpoint)",
                res["status"] == "STOP" and "free phase of a contrast session" in txt
                and "scaffold" not in txt and "scaffold_absorption" not in res["report"].read_text()
                and rep["stop"]["bar"] == stages.WITHHELD_CLASS and "round" not in rep["stop"]
                and ck["stop"]["bar"] == "scaffold_absorption" and len(ck["sessions"]) == 1
                and ck["stop"]["round"] == {"phase": "free", "n": 6, "index": 1}
                and ck["stage_end"]["status"] == "STOP" and "n=6" not in txt and "round 6" not in txt,
                txt.splitlines()[-4:-3])
            ah = adj_of(res)
            evh = ah["events"][0]
            fired_choice = ck["sessions"][0]["choices"][1]
            rep_txt = res["report"].read_text()
            chk("m_sessions: the contrast free-phase trigger's adjudication excerpt holds the fired round "
                "only (its header, generation and audit) and lists the pick its header reveals; neither "
                "the report nor stdout carries any of it",
                evh["kind"] == "hair_trigger" and evh["bar"] == "scaffold_absorption"
                and evh["session"]["template"] == "A0" and evh["session"]["contrast"] is True
                and len(evh["rounds"]) == 1 and evh["rounds"][0]["n"] == 6
                and evh["rounds"][0]["generation"] == "<|im_end|>"
                and evh["rounds"][0]["header"].startswith("[round 6 ")
                and fired_choice["pick"] in evh["rounds"][0]["header"]
                and evh["picks_revealed"] == [{**evh["session"], "ci": 1, "n": 6, "pick": fired_choice["pick"]}]
                and evh["rounds"][0]["header"] not in rep_txt and evh["rounds"][0]["header"] not in txt
                and "picks_revealed" not in rep_txt and "<|im_end|>" not in txt
                and "ADJUDICATION " in txt, evh["rounds"][0]["header"][:20])
            cbytes = res["checkpoint"].read_bytes()
            _, exc2, txt2 = gate("Q-F0", "time", QT, root, adapter_for("Q-F0", "time", QT), resume=True)
            with env_pod("podB"):
                _, exc3, txt3 = gate("Q-F0", "time", QT, root, adapter_for("Q-F0", "time", QT), resume=True)
            _, exc4, txt4 = gate("Q-F0", "time", QT, root, adapter_for("Q-F0", "time", QT))
            chk("m_sessions: a resume never lifts a STOP -- refused 'STAGE ENDED (STOP' on its own pod "
                "and on a new pod (never set aside, the checkpoint untouched)",
                all(isinstance(e, SystemExit) and "STAGE ENDED" in str(e) and "(STOP" in str(e)
                    for e in (exc2, exc3))
                and res["checkpoint"].read_bytes() == cbytes
                and not list(res["checkpoint"].parent.glob("*.podchange-*")), str(exc3)[:70])
            refusals = [str(e) for e in (exc2, exc3, exc4)] + [txt2, txt3, txt4]
            chk("m_sessions: every re-invocation of the stage a contrast free-phase trigger stopped names "
                "it by phase alone, as its announcement -- no class, round or n in the refusal or on stdout",
                all("free phase of a contrast session (A0 s=0)" in str(e) for e in (exc2, exc3, exc4))
                and not any(w in t for t in refusals
                            for w in ("scaffold", ck["stop"]["bar"], "n=6", "round 6", "index")),
                str(exc4)[:120])

            # --- G-VER: a harness defect is caught before the record is written -----------
            gver = {}
            for nm, fn, want in (("gver_bytes", bump_text, "template_breakage"),
                                 ("gver_seed", bump_seed, "schedule_mismatch")):
                with tampered_runner(fn, lambda sc, pc: sc.template == "A0s"):
                    res, _, txt = gate("Q-F0", "time", QT, fresh(nm), adapter_for("Q-F0", "time", QT))
                ck = ckpt_of(res)
                ev = adj_of(res)["events"][0]
                gver[nm] = (res["status"] == "STOP" and ck["stop"]["bar"] == want
                            and [r["template"] for r in ck["sessions"]] == ["A0"]
                            and ck["stop"]["record"]["verified"] is False and ck["stop"]["round"] is None
                            and f"BAR {want} FIRED template=A0s" in txt
                            and "time A0s" not in txt
                            and ev["kind"] == "harness" and ev["bar"] == want and ev["rounds"] == []
                            and ev["problems"] == ck["stop"]["problems"] and ev["problems"]
                            and ev["session"]["template"] == "A0s" and ev["picks_revealed"] == []
                            and [e["launched"] for e in ck["provenance"]] == [2])
            chk("m_sessions: G-VER -- a transcript-byte defect (template_breakage) and a seed defect "
                "(schedule_mismatch) STOP the stage; the record is quarantined, never a session; the "
                "untampered A0 session stands; the excerpt holds the verifier's problems (no round) and "
                "the quarantined launch is counted in the invocation's provenance", all(gver.values()), gver)
            chk("m_sessions: stages' run_session_qwen reference is restored after the wrapping",
                stages.run_session_qwen is runner_qwen.run_session_qwen)

            # --- the prior stage gates the next; no qualification before a G-ID artifact ----
            adq = adapter_for("Q-F0", "qual", QQ)
            _, exq, _ = gate("Q-F0", "qual", QQ, fresh("qual_no_gid"), adq, prior_ckpt=prior_time)
            adi = adapter_for("Q-F0", "id", {"A0s": 16})
            _, exi, _ = gid(fresh("gid_after_stop"), adi, prior_time_stop)
            _, exn, _ = gid(fresh("gid_no_prior"), adapter_for("Q-F0", "id", {"A0s": 16}), None)
            chk("m_sessions: G-F0m-Qwen refuses without the unit's G-ID artifact, G-ID refuses after a "
                "G-TIME STOP and without a prior checkpoint -- before any generation",
                isinstance(exq, SystemExit) and "G-ID ARTIFACT ABSENT" in str(exq) and not adq.calls
                and isinstance(exi, SystemExit) and "PRIOR STAGE STOP" in str(exi) and not adi.calls
                and isinstance(exn, SystemExit) and "PRIOR STAGE REQUIRED" in str(exn),
                (str(exq)[:40], str(exi)[:40], str(exn)[:40]))
            rootg = fresh("gid_renders")
            adg = adapter_for("Q-F0", "id", {"A0s": 16})
            _, exg, _ = capture(stages.run_gid_pair, adg, unit="Q-F0",
                                identity_extra=xtra(None, renders_sha16="0" * 16),
                                prior_ckpt=prior_time, out_root=rootg)
            chk("m_sessions: G-ID refuses a renders sha16 that is not the renders of record (RENDERS "
                "MISMATCH) before any generation or checkpoint (finding N1)",
                isinstance(exg, SystemExit) and "RENDERS MISMATCH" in str(exg) and not adg.calls
                and not (rootg / "ckpt").exists() and not guard.gid_artifact_path("Q-F0").exists(),
                str(exg)[:60])

        # --- G-ID-F0m ------------------------------------------------------------------
        root = fresh("gid_pass")
        with gates_at(root / "gates"):
            ad = adapter_for("Q-F0", "id", {"A0s": 16})
            res, exc, txt = gid(root, ad, prior_time)
            art = json.loads(guard.gid_artifact_path("Q-F0").read_text())
            bid = resume.backend_identifier(ad.provenance())
            bid_y = resume.backend_identifier(on_backend_y(testing.ScriptedAdapter()).provenance())
            paths = [c["cached"] for c in ad.calls]
            chk("m_sessions: G-ID PASS at two complete identical pairs (j = 0, 1); uncached first at "
                "every index; the artifact records its backend and licenses the cached path on that "
                "backend only",
                res["status"] == "PASS" and [p["j"] for p in res["pairs"]] == [0, 1]
                and paths == [False] * 10 + [True] * 10 + [False] * 10 + [True] * 10
                and (art["verdict"], art["n_pairs"], art["pairs_identical"]) == ("PASS", 2, [True, True])
                and art["identity"]["backend_identifier"] == bid and bid != bid_y
                and guard.cached_path_admitted("Q-F0", "qual", backend_identifier=bid) is True
                and guard.cached_path_admitted("Q-F0", "qual", backend_identifier=bid_y) is False
                and guard.cached_path_admitted("Q-F0", "time", backend_identifier=bid) is False
                and ckpt_of(res)["stage_end"]["status"] == "PASS"
                and "STAGE G-ID-F0m PASS path=cached+uncached" in txt, res["status"])
            ad = adapter_for("Q-F0", "qual", QQ)
            res, exc, txt = gate("Q-F0", "qual", QQ, fresh("qual_cached"), ad, lp="cached",
                                 prior_ckpt=prior_time)
            chk("m_sessions: after a G-ID PASS on this backend the qualification stage locked 'cached' "
                "runs cached (every generate cached=True; identity path 'cached'; the STAGE line says so)",
                res["status"] == "PASS" and all(c["cached"] is True for c in ad.calls)
                and ckpt_of(res)["identity"]["path"] == "cached" and "path=cached" in txt, res["status"])
            ady = on_backend_y(adapter_for("Q-F0", "qual", QQ))
            _, exy, _ = gate("Q-F0", "qual", QQ, fresh("qual_backend_y"), ady, lp="cached",
                             prior_ckpt=prior_time)
            adu = adapter_for("Q-F0", "qual", QQ)
            _, exu, _ = gate("Q-F0", "qual", QQ, fresh("qual_lock_uncached"), adu, lp="uncached",
                             prior_ckpt=prior_time)
            chk("m_sessions: the G-ID PASS of backend X licenses nothing on backend Y -- a qualification "
                "locked 'cached' there is refused (PATH MISMATCH), as is one locked 'uncached' where "
                "the licence says cached; neither generates",
                isinstance(exy, SystemExit) and "PATH MISMATCH" in str(exy) and not ady.calls
                and isinstance(exu, SystemExit) and "PATH MISMATCH" in str(exu) and not adu.calls,
                (str(exy)[:60], str(exu)[:60]))
            _, exc, _ = gid(fresh("gid_again"), adapter_for("Q-F0", "id", {"A0s": 16}), prior_time)
            chk("m_sessions: an existing G-ID artifact is never overwritten",
                isinstance(exc, SystemExit) and "G-ID ARTIFACT EXISTS" in str(exc))
        root = fresh("gid_fail")
        with gates_at(root / "gates"):
            rd = lambda t, s, n, c: "Forty." if c["cached"] and s == 0 and n == 7 else None
            res, exc, txt = gid(root, adapter_for("Q-F0", "id", {"A0s": 16}, rd), prior_time)
            art = json.loads(guard.gid_artifact_path("Q-F0").read_text())
            chk("m_sessions: G-ID FAILs on a scripted cached/uncached divergence (j = 0); the bar "
                "fires; the artifact grants nothing; FAIL persisted as stage_end naming the bar",
                res["status"] == "FAIL" and art["verdict"] == "FAIL" and art["pairs_identical"] == [False]
                and "gid_divergence@G-ID-F0m FIRED" in txt
                and ckpt_of(res)["stage_end"]["fired"] == ["gid_divergence@G-ID-F0m"]
                and guard.cached_path_admitted("Q-F0", "qual", backend_identifier=bid) is False,
                res["status"])
            # --- qualification, uncached (the G-ID artifact exists and grants nothing) -----
            ad = adapter_for("Q-F0", "qual", QQ)
            res, exc, txt = gate("Q-F0", "qual", QQ, fresh("qual_uncached"), ad, prior_ckpt=prior_time)
            ck = ckpt_of(res)
            prior_qual = res["checkpoint"]
            order = [(r["template"], r["s"]) for r in ck["sessions"]]
            want = schedule.gate_launch_order([("A0", 8), ("A0s", 16)])
            chk("m_sessions: G-F0m-Qwen runs 24 sessions in the rotation (A0/A0s, then A0s), "
                "uncached after a G-ID FAIL; bar silent; PASS; the prior G-TIME recorded",
                res["status"] == "PASS" and order == want and len(order) == 24
                and all(c["cached"] is False for c in ad.calls)
                and rep_of(res)["bars"][0]["name"] == "round_degeneracy@G-F0m-Qwen"
                and ck["prior"]["status"] == "PASS" and ck["prior"]["stage"] == "time", res["status"])
            reads = json.loads(res["reads"].read_text())
            chk("m_sessions: qualification reads -- contrast stripped to forced rounds, sham "
                "redacted, no choice field anywhere",
                all((all(x["phase"] == "forced" for x in r["rounds"]) if r["contrast"]
                     else "[config]" in r["transcript"]) for r in reads["sessions"])
                and '"choices"' not in res["reads"].read_text())
            # ruling (h) must not fire at the qualification stage: a contrast forced exclusion
            # keeps its class on stdout, in the report and in the stripped read (m:263, m:283)
            rqc = lambda t, s, n, c: "Config choice one." if t == "A0" and s == 0 and n == 2 else None
            resqc, _, txtqc = gate("Q-F0", "qual", QQ, fresh("qual_forced_class"),
                                   adapter_for("Q-F0", "qual", QQ, rqc), prior_ckpt=prior_time)
            cbq = rep_of(resqc)["stage_report"]["templates"]["A0"]
            rdq = [r for r in json.loads(resqc["reads"].read_text())["sessions"]
                   if r["template"] == "A0" and r["s"] == 0][0]
            chk("m_sessions: ruling (h) is G-TIME only (must not fire) -- at G-F0m-Qwen a contrast forced v2 "
                "exclusion still prints 'qual A0 s=0 excluded:audit@forced', the report counts it by class "
                "(audit@forced 1; claims v2 1; no per-session block) and the stripped read keeps its class",
                resqc["status"] == "PASS" and "qual A0 s=0 excluded:audit@forced" in txtqc.splitlines()
                and cbq["excluded_at_forced"]["audit@forced"] == 1 and cbq["forced"]["claims"]["v2"] == 1
                and "per_session" not in cbq and rdq["exclusion"]["class"] == "v2"
                and rdq["exclusion"]["phase"] == "forced" and "audit" in rdq["rounds"][1],
                (cbq.get("excluded_at_forced"), resqc["status"]))
            # the contrast arm's first-read flags (N11), both directions on the same stage
            flags = {}
            for nm, low in (("high mass", False), ("low mass", True)):
                rq, _, _ = gate("Q-F0", "qual", QQ, fresh(f"qual_flags_{nm.replace(' ', '_')}"),
                                adapter_for("Q-F0", "qual", QQ, picks=first_label(low)),
                                prior_ckpt=prior_time)
                ckf = ckpt_of(rq)
                dom = [r for r in ckf["sessions"] if r["template"] == "A0" and r["domain"]]
                flags[nm] = (rep_of(rq)["contrast_first_read_flags"]["A0"], len(dom),
                             sum(r["choices"][0]["low_label_mass"] for r in dom))
            hi, lo = flags["high mass"], flags["low mass"]
            chk("m_sessions: the qualification report carries the contrast arm's first-read flags over "
                "the FIRST read of each contrast domain session -- 0 flagged at high label mass, every "
                "one at low label mass; counts only, no label",
                hi[0]["reads"] == hi[1] > 0 and hi[0]["low_label_mass"] == 0 == hi[2]
                and lo[0]["reads"] == lo[1] > 0 and lo[0]["low_label_mass"] == lo[1] == lo[2]
                and hi[0]["scope"] == "first reads of domain sessions"
                and "contrast_first_read_flags" in rep_of(res), (hi[0], lo[0]))
            adc = adapter_for("Q-F0", "qual", QQ)
            _, exc, _ = gate("Q-F0", "qual", QQ, fresh("qual_lock_cached"), adc, lp="cached",
                             prior_ckpt=prior_time)
            chk("m_sessions: after a G-ID FAIL a qualification locked 'cached' is refused (PATH "
                "MISMATCH) before any generation",
                isinstance(exc, SystemExit) and "PATH MISMATCH" in str(exc) and not adc.calls)
        root = fresh("gid_advance")
        with gates_at(root / "gates"):
            ri = lambda t, s, n, c: "{Pc} is the answer." if s == 0 and n == 2 else None
            res, exc, txt = gid(root, adapter_for("Q-F0", "id", {"A0s": 16}, ri), prior_time)
            pr = res["pairs"]
            chk("m_sessions: an incomplete identical pair advances j (j = 0 excluded in both paths; "
                "PASS at j = 1, 2)",
                res["status"] == "PASS" and [(p["j"], p["complete"], p["identical"]) for p in pr]
                == [(0, False, True), (1, True, True), (2, True, True)], pr)
        root = fresh("gid_nd")
        with gates_at(root / "gates"):
            rn = lambda t, s, n, c: "{Qc}." if n == 1 else None
            res, exc, txt = gid(root, adapter_for("Q-F0", "id", {"A0s": 16}, rn), prior_time)
            art = json.loads(guard.gid_artifact_path("Q-F0").read_text())
            chk("m_sessions: past j = 15 without two complete pairs G-ID is NOT-DETERMINED, never PASS",
                res["status"] == "NOT-DETERMINED" and len(res["pairs"]) == 16
                and art["verdict"] == "NOT-DETERMINED"
                and guard.cached_path_admitted("Q-F0", "qual", backend_identifier=bid) is False,
                res["status"])
        root = fresh("gid_tamper")
        with gates_at(root / "gates"):
            with tampered_runner(bump_text, lambda sc, pc: pc is True and sc.s == 1):
                res, exc, txt = gid(root, adapter_for("Q-F0", "id", {"A0s": 16}), prior_time)
            ck = ckpt_of(res)
            chk("m_sessions: G-VER at G-ID -- a tampered cached half (j = 1) STOPs the stage; the record "
                "is quarantined (verified False), never a session; no G-ID artifact is written",
                res["status"] == "STOP" and ck["stop"]["bar"] == "template_breakage"
                and ck["stop"]["record"]["verified"] is False
                and (1, "cached") not in {(r["s"], r["path"]) for r in ck["sessions"]}
                and len(ck["sessions"]) == 3 and all(r["verified"] is True for r in ck["sessions"])
                and not guard.gid_artifact_path("Q-F0").exists()
                and ck["stage_end"]["status"] == "STOP", res["status"])

        # --- G-ID: an interrupted finish re-finishes; its artifact is accepted only if identical --
        root = fresh("gid_refinish")
        with gates_at(root / "gates"):
            with cut_at_end(has_end):
                _, exr, _ = gid(root, adapter_for("Q-F0", "id", {"A0s": 16}), prior_time)
            cpg = root / "ckpt" / "Q-F0_id.json"
            artp = guard.gid_artifact_path("Q-F0")
            art_b, rep_b = artp.read_bytes(), (root / "reports" / "Q-F0_id_report.json").read_bytes()
            mid = json.loads(cpg.read_text())
            adx = adapter_for("Q-F0", "id", {"A0s": 16})
            _, exx, _ = gid(root, adx, prior_time, ckpt_path=root / "ckpt" / "Q-F0_id.rerun.json")
            adr = adapter_for("Q-F0", "id", {"A0s": 16})
            resr, _, txtr = gid(root, adr, prior_time)
            chk("m_sessions: G-ID killed after its artifact and report were written but before its end "
                "was persisted (the end pending on disk) -- a fresh G-ID at another checkpoint is refused "
                "(G-ID ARTIFACT EXISTS); a PLAIN re-invocation of the pending one re-finishes: it launches "
                "nothing, accepts the byte-identical artifact, re-derives the identical report and persists "
                "PASS",
                isinstance(exr, stages._Interrupt) and "stage_end" not in mid and "end_pending" in mid
                and isinstance(exx, SystemExit) and "G-ID ARTIFACT EXISTS" in str(exx) and not adx.calls
                and resr is not None and resr["status"] == "PASS" and not adr.calls
                and "RE-FINISH G-ID-F0m" in txtr and artp.read_bytes() == art_b
                and (root / "reports" / "Q-F0_id_report.json").read_bytes() == rep_b
                and ckpt_of(resr)["stage_end"]["status"] == "PASS"
                and "end_pending" not in ckpt_of(resr), (type(exr).__name__, (resr or {}).get("status")))
        root = fresh("gid_refinish_bad")
        with gates_at(root / "gates"):
            with cut_at_end(has_end):
                gid(root, adapter_for("Q-F0", "id", {"A0s": 16}), prior_time)
            artp = guard.gid_artifact_path("Q-F0")
            artp.write_text(artp.read_text(encoding="utf-8").replace('"verdict"', ' "verdict"', 1),
                            encoding="utf-8")
            bad_b = artp.read_bytes()
            rep_b = (root / "reports" / "Q-F0_id_report.json").read_bytes()
            adb = adapter_for("Q-F0", "id", {"A0s": 16})
            _, exb, _ = gid(root, adb, prior_time, resume=True)
            chk("m_sessions: a G-ID artifact that differs from the one the finish re-derives is refused "
                "(G-ID ARTIFACT DIFFERS): never overwritten, nothing written, the end not persisted",
                isinstance(exb, SystemExit) and "G-ID ARTIFACT DIFFERS" in str(exb) and not adb.calls
                and artp.read_bytes() == bad_b
                and (root / "reports" / "Q-F0_id_report.json").read_bytes() == rep_b
                and "stage_end" not in json.loads((root / "ckpt" / "Q-F0_id.json").read_text()),
                str(exb)[:60])

        with gates_at(base / "no-gates"):
            # --- OLMo: the pod id, the G-TIME pause, the qualification after a pause ---------
            with olmo_stub_startup():
                with env_pod(None):
                    adn = adapter_for("OLMo-sft", "time", OT)
                    _, exnp, _ = gate("OLMo-sft", "time", OT, fresh("olmo_nopod"), adn)
                with env_pod("  "):
                    _, exbp, _ = gate("OLMo-sft", "time", OT, fresh("olmo_blankpod"),
                                      adapter_for("OLMo-sft", "time", OT))
                with env_pod("podO"):
                    rp = lambda t, s, n, c: "{COMMON}" if t == "A0s-OLMo-sft" and n == 3 else None
                    r1 = lambda t, s, n, c: "{COMMON}" if t == "A0s-OLMo-sft" and n == 1 else None
                    resp, _, txtp = gate("OLMo-sft", "time", OT, fresh("olmo_pause"),
                                         adapter_for("OLMo-sft", "time", OT, rp))
                    resc, _, _ = gate("OLMo-sft", "time", OT, fresh("olmo_clean"),
                                      adapter_for("OLMo-sft", "time", OT))
                    res1, _, _ = gate("OLMo-sft", "time", OT, fresh("olmo_r1"),
                                      adapter_for("OLMo-sft", "time", OT, r1))
            chk("m_sessions: an OLMo stage refuses to start without $RUNPOD_POD_ID (absent or blank) "
                "before any generation; with it the stage runs",
                isinstance(exnp, SystemExit) and "POD ID ABSENT" in str(exnp) and not adn.calls
                and isinstance(exbp, SystemExit) and "POD ID ABSENT" in str(exbp)
                and resc is not None and resc["status"] == "PASS", str(exnp)[:60])
            fired = lambda res: {b["name"].split("@")[0]: b["fired"] for b in rep_of(res)["bars"]}
            chk("m_sessions: OLMo G-TIME -- a round-3 echo on the sham session PAUSEs (pause fires, "
                "the bar's critical 2 unreached; PAUSE persisted); a clean stage PASSes with the "
                "pause silent",
                (resp["status"], fired(resp), resc["status"], fired(resc))
                == ("PAUSE", {"round_degeneracy": False, "gtime_pause": True},
                    "PASS", {"round_degeneracy": False, "gtime_pause": False})
                and ckpt_of(resp)["stage_end"]["status"] == "PAUSE",
                (fired(resp), fired(resc)))
            chk("m_sessions: OLMo G-TIME -- a round-1 claim fires bar and pause; the STOP governs",
                res1["status"] == "STOP" and fired(res1) == {"round_degeneracy": True, "gtime_pause": True})
            evp = adj_of(resp)["events"][0]
            ckp_ = ckpt_of(resp)
            sham_p = [r for r in ckp_["sessions"] if r["template"] == "A0s-OLMo-sft"][0]
            chk("m_sessions: the OLMo G-TIME pause's adjudication excerpt holds the claimed sham round "
                "(forced round 3: header, generation, audit) and reveals no pick; the PASS writes none",
                evp["event"] == "PAUSE" and evp["kind"] == "bars"
                and [b.split("@")[0] for b in evp["bars"]] == ["gtime_pause"]
                and [(x["template"], x["phase"], x["n"]) for x in evp["rounds"]]
                == [("A0s-OLMo-sft", "forced", 3)]
                and evp["rounds"][0]["generation"] == sham_p["rounds"][2]["text"]
                and evp["rounds"][0]["audit"]["claim"] == "echo" and evp["picks_revealed"] == []
                and resc["adjudication"] is None, evp.get("bars"))
            # the seat's note (2026-10-06): at G-TIME-OLMo a claim at realised n <= 2 fires the
            # bar (STOP), which subsumes the pause; the STOP governs -- the pause is recorded
            # as fired and not separately acted on. From n = 3 the pause alone (PAUSE).
            sg = {"r1 echo": lambda t, s, n, c: "{COMMON}" if t == "A0s-OLMo-sft" and n == 1 else None,
                  "r2 AuditSpec": lambda t, s, n, c: ("Config choice one." if t == "A0s-OLMo-sft" and n == 2
                                                      else None),
                  "r3 AuditSpec": lambda t, s, n, c: ("Config choice one." if t == "A0s-OLMo-sft" and n == 3
                                                      else None)}
            sg_got = {}
            with olmo_stub_startup():
                with env_pod("podO"):
                    for nm, rule_ in sg.items():
                        tag_ = nm.replace(" ", "_")
                        res_, _, txt_ = gate("OLMo-sft", "time", OT, fresh(f"olmo_governs_{tag_}"),
                                             adapter_for("OLMo-sft", "time", OT, rule_))
                        ex_q = []
                        if res_["status"] == "STOP":
                            for adj_ in ("seat: selftest -- the pause adjudicated", None):
                                adq_ = adapter_for("OLMo-sft", "qual", OQ)
                                _, exq_, _ = gate("OLMo-sft", "qual", OQ, fresh(f"olmo_after_{tag_}_{bool(adj_)}"),
                                                  adq_, prior_ckpt=res_["checkpoint"], prior_adjudication=adj_)
                                ex_q.append((exq_, len(adq_.calls)))
                        sg_got[nm] = (res_, txt_, ex_q)

            def governs(nm, n_real):
                res_, txt_, ex_q = sg_got[nm]
                ck_, ev_ = ckpt_of(res_), adj_of(res_)["events"]
                bar_ = [b for b in rep_of(res_)["bars"] if b["name"].startswith("round_degeneracy@")][0]
                sham_ = [r for r in ck_["sessions"] if r["template"] == "A0s-OLMo-sft"][0]
                return (res_["status"] == "STOP" and fired(res_) == {"round_degeneracy": True, "gtime_pause": True}
                        and (bar_["k"], bar_["n"], bar_["crit"]) == (1, n_real, 1) and len(sham_["rounds"]) == n_real
                        and ck_["stage_end"]["status"] == "STOP"
                        and sorted(x.split("@")[0] for x in ck_["stage_end"]["fired"])
                        == ["gtime_pause", "round_degeneracy"]
                        and len(ev_) == 1 and ev_[0]["event"] == "STOP" and ev_[0]["kind"] == "bars"
                        and sorted(x.split("@")[0] for x in ev_[0]["bars"]) == ["gtime_pause", "round_degeneracy"]
                        and "STAGE G-TIME-OLMo-sft STOP path=uncached" in txt_ and "STAGE G-TIME-OLMo-sft PAUSE" not in txt_
                        and isinstance(ex_q[0][0], SystemExit) and "PRIOR ADJUDICATION REFUSED" in str(ex_q[0][0])
                        and isinstance(ex_q[1][0], SystemExit) and "PRIOR STAGE STOP" in str(ex_q[1][0])
                        and ex_q[0][1] == ex_q[1][1] == 0)
            r3_res, r3_txt, _ = sg_got["r3 AuditSpec"]
            r3_bar = [b for b in rep_of(r3_res)["bars"] if b["name"].startswith("round_degeneracy@")][0]
            chk("m_sessions: OLMo G-TIME -- the STOP governs at realised n <= 2 (a round-1 echo, a round-2 "
                "AuditSpec claim on the sham session): bar (k 1, critical 1) and pause both fire, status and "
                "stage_end STOP, ONE STOP event naming both, no PAUSE line; the pause is not separately acted on "
                "(the qualification refuses its adjudication -- PRIOR ADJUDICATION REFUSED -- and runs on "
                "nothing: PRIOR STAGE STOP, zero generations); at n = 3 (AuditSpec) the bar's critical 2 is "
                "unreached and the pause alone PAUSEs",
                governs("r1 echo", 1) and governs("r2 AuditSpec", 2)
                and r3_res["status"] == "PAUSE" and fired(r3_res) == {"round_degeneracy": False, "gtime_pause": True}
                and (r3_bar["k"], r3_bar["n"], r3_bar["crit"]) == (1, 3, 2)
                and ckpt_of(r3_res)["stage_end"]["status"] == "PAUSE"
                and "STAGE G-TIME-OLMo-sft PAUSE path=uncached" in r3_txt,
                {k: (v[0]["status"], [str(e)[:40] for e, _ in v[2]]) for k, v in sg_got.items()})
            with olmo_stub_startup():
                with env_pod("podO2"):
                    _, expa, _ = gate("OLMo-sft", "time", OT, resp["report"].parents[1],
                                      adapter_for("OLMo-sft", "time", OT), resume=True)
                    ado = adapter_for("OLMo-sft", "qual", OQ)
                    _, exoq, _ = gate("OLMo-sft", "qual", OQ, fresh("olmo_qual_noadj"), ado,
                                      prior_ckpt=resp["checkpoint"])
                    adj_text = "seat: the round-3 echo is a banner copy (selftest); qualification runs"
                    resq, exq2, txtq = gate("OLMo-sft", "qual", OQ, fresh("olmo_qual_adj"),
                                            adapter_for("OLMo-sft", "qual", OQ),
                                            prior_ckpt=resp["checkpoint"], prior_adjudication=adj_text)
            ckq = ckpt_of(resq) if resq else {}
            chk("m_sessions: a PAUSEd OLMo G-TIME is never re-run on a new pod (STAGE ENDED (PAUSE)); "
                "its qualification refuses without the seat's adjudication and runs with it, the text "
                "in the checkpoint only",
                isinstance(expa, SystemExit) and "STAGE ENDED" in str(expa) and "(PAUSE)" in str(expa)
                and isinstance(exoq, SystemExit) and "PRIOR STAGE PAUSE" in str(exoq) and not ado.calls
                and resq is not None and resq["status"] == "PASS"
                and ckq["prior"]["adjudication"] == adj_text and adj_text not in txtq
                and "banner copy" not in resq["report"].read_text(), (str(expa)[:50], str(exoq)[:50]))
            chk("m_sessions: stages' olmo_startup reference is restored after the substitution",
                stages.olmo_startup is runner_olmo.olmo_startup)

            # --- gate-stage pod change: set aside only an interrupted stage ---------------
            root = fresh("pod_gate")
            stop_at = lambda t, s, n, c: t == "A0s" and n == 2
            with env_pod("podA"):
                _, exc, _ = gate("Q-F0", "time", QT, root, adapter_for("Q-F0", "time", QT, None, stop_at))
            cpath = root / "ckpt" / "Q-F0_time.json"
            before = cpath.read_bytes()
            with env_pod("podB"):
                res, exc2, txt = gate("Q-F0", "time", QT, root, adapter_for("Q-F0", "time", QT),
                                      resume=True)
            aside = sorted(cpath.parent.glob("Q-F0_time.json.podchange-*"))
            ck = ckpt_of(res) if res else {}
            chk("m_sessions: a gate stage interrupted by a pod change sets the old checkpoint aside "
                "(byte-identical, renamed) and restarts from its first session",
                isinstance(exc, stages._Interrupt) and res is not None and res["status"] == "PASS"
                and len(aside) == 1 and aside[0].read_bytes() == before and "POD CHANGE" in txt
                and ck["state"]["set_aside"] == [aside[0].name]
                and [r["template"] for r in ck["sessions"]] == ["A0", "A0s"]
                and ck["state"]["pod_id_seen"] == "podB", (exc, aside))
            done_bytes = cpath.read_bytes()
            with env_pod("podC"):
                _, exd, _ = gate("Q-F0", "time", QT, root, adapter_for("Q-F0", "time", QT), resume=True)
            chk("m_sessions: a FINISHED gate stage re-invoked on another pod is refused 'STAGE ENDED "
                "(PASS)'; nothing more is set aside and the checkpoint is untouched",
                isinstance(exd, SystemExit) and "STAGE ENDED" in str(exd) and "(PASS)" in str(exd)
                and len(sorted(cpath.parent.glob("Q-F0_time.json.podchange-*"))) == 1
                and cpath.read_bytes() == done_bytes, str(exd)[:60])

            # --- the campaign ---------------------------------------------------------------
            CF = {"A0": 24, "A0s": 20}
            CL = {"A0": 64, "A0s": 32}

            def camp(unit, root, ad, floors=CF, lcs=CL, cap=10.0, prior=None, lp="uncached", **kw):
                return capture(stages.run_campaign, ad, unit=unit, floors=floors, launch_counts=lcs,
                               hour_cap=cap, identity_extra=kw.pop("identity_extra", xtra(lp)),
                               prior_ckpt=prior or prior_qual,
                               substrate="qwen" if unit == "Q-F0" else "olmo", out_root=root, **kw)

            rootc = fresh("camp_clean")
            resc, _, txtc = camp("Q-F0", rootc, adapter_for("Q-F0", "campaign", CL))
            ckc, repc = ckpt_of(resc), rep_of(resc)
            seq = [r["template"] for r in ckc["sessions"]]
            sham_ms = sum(resume.session_ms(r) for r in ckc["sessions"] if not r["contrast"])
            chk("m_sessions: campaign -- strict rotation A0/A0s, A0s leaves at its floor (20), A0 runs "
                "to 24; COMPLETE at 44 launches; look 1 at 40 and the end look silent; looks counted "
                "2 = ceil(44/40)",
                resc["status"] == "COMPLETE" and seq == ["A0", "A0s"] * 20 + ["A0"] * 4
                and [r["s"] for r in ckc["sessions"] if r["template"] == "A0"] == list(range(24))
                and len(ckc["looks"]) == 1 and not ckc["looks"][0]["result"]["fired"]
                and ckc["campaign"]["end_look"]["look"] == "end"
                and not ckc["campaign"]["end_look"]["fired"] and repc["looks_count"] == 2
                and stages.exit_code(resc["status"]) == 0, resc["status"])
            chk("m_sessions: the campaign's identity n is the committed schedule's (L is a projection, "
                "recorded beside); its report carries the sham arm's ms only and whether the cap is "
                "reached -- no total that includes contrast sessions",
                ckc["identity"]["n"] == {"A0": 2624, "A0s": 960}
                and repc["launch_counts_projection"] == CL and repc["schedule_n"] == {"A0": 2624, "A0s": 960}
                and repc["sham_generation_ms"] == sham_ms
                and repc["sham_generation_ms"] < ckc["state"]["hour_cap_ms_used"]
                and repc["hour_cap_reached"] is False and "generation_ms_used" not in repc
                and "hour_cap_ms_used" not in json.dumps(repc), (sham_ms, ckc["state"]["hour_cap_ms_used"]))
            rootp = fresh("camp_pause")
            rv = lambda t, s, n, c: "Config choice one." if t == "A0s" and n == 6 else None
            resp, _, txtp = camp("Q-F0", rootp, adapter_for("Q-F0", "campaign", CL, rv))
            ckp = ckpt_of(resp)
            lk = ckp["looks"][0]["result"] if ckp["looks"] else {}
            chk("m_sessions: campaign -- the sham round_degeneracy look fires at launch 40 and PAUSEs "
                "the unit (exit non-zero), the Fisher and absolute guards silent; the look reports "
                "read flags per arm",
                resp["status"] == "PAUSE" and len(ckp["sessions"]) == 40 and lk.get("fired")
                and [r["fired"] for r in lk["results"]] == [True, False, False]
                and "round_degeneracy@campaign-Q-F0 FIRED" in txtp
                and lk["arms"]["A0s"]["read_flags"]["reads"] > 0
                and lk["arms"]["A0"]["read_flags"]["reads"] == lk["arms"]["A0"]["domain"]
                and stages.exit_code(resp["status"]) != 0, [r["message"] for r in lk.get("results", [])])
            evl = adj_of(resp)["events"]
            chk("m_sessions: a campaign look pause's adjudication excerpt holds the counts only -- the "
                "look's results and arm counts, no round, no pick",
                [(e["event"], e["kind"], e["at_launches"]) for e in evl] == [("PAUSE", "look", 40)]
                and "rounds" not in evl[0] and evl[0]["picks_revealed"] == []
                and evl[0]["counts"] == lk and "transcript" not in json.dumps(evl)
                and "header" not in json.dumps(evl), [e["kind"] for e in evl])
            cp_bytes = (rootp / "ckpt" / "Q-F0_campaign.json").read_bytes()
            rp_bytes = Path(resp["report"]).read_bytes()
            ad_show = adapter_for("Q-F0", "campaign", CL, rv)
            res_show, excp, txt_show = camp("Q-F0", rootp, ad_show, resume=True)
            chk("m_sessions: a paused campaign resumed with neither the seat's adjudication nor the PI's stop "
                "is shown its pause (finding R6): PAUSE (exit 3), its report re-derived byte-identical, "
                "nothing launched, the checkpoint unchanged",
                excp is None and res_show is not None and res_show["status"] == "PAUSE"
                and stages.exit_code(res_show["status"]) == 3 and not ad_show.calls
                and (rootp / "ckpt" / "Q-F0_campaign.json").read_bytes() == cp_bytes
                and Path(res_show["report"]).read_bytes() == rp_bytes
                and "is paused (look, at 40 launches)" in txt_show, str(excp)[:80])
            roster_adj = "selftest: the ridge/saddle echoes are banner copies; What is prism? continue"
            resq, excq, _ = camp("Q-F0", rootp, adapter_for("Q-F0", "campaign", CL, rv), resume=True,
                                 adjudication=roster_adj)
            ckq = ckpt_of(resq) if resq else {}
            repq = rep_of(resq) if resq else {}
            chk("m_sessions: a paused campaign resumes only with the seat's adjudication named -- one "
                "naming roster labels included; it runs to its floors (44), its fired end look pauses "
                "again (terminal), and the report is written with the pauses as adjudicated/sha only",
                excq is None
                and resq["status"] == "PAUSE" and len(ckq["sessions"]) == 44
                and ckq["campaign"]["pauses"][0]["adjudication"] == roster_adj
                and ckq["campaign"]["terminal"]["status"] == "COMPLETE"
                and repq["status"] == "PAUSE"
                and repq["pauses"][0] == {"kind": "look", "at_launches": 40, "adjudicated": True,
                                          "adjudication_sha16": hashlib.sha256(
                                              roster_adj.encode()).hexdigest()[:16]}
                and repq["pauses"][1]["adjudicated"] is False and "ridge" not in json.dumps(repq),
                (resq or {}).get("status"))
            evq = adj_of(resq)["events"] if resq else []
            chk("m_sessions: the end-look pause rewrites the campaign's excerpt with one event per pause "
                "(look 1, then the end look), counts only; the seat's adjudication text is not copied",
                [(e["kind"], e["at_launches"]) for e in evq] == [("look", 40), ("end_look", 44)]
                and evq[1]["counts"] == ckq["campaign"]["end_look"] and roster_adj not in json.dumps(evq),
                [e["kind"] for e in evq])
            # the end look on a multiple of 40 IS the look recorded there
            roote = fresh("camp_endlook40")
            fl40 = {"A0": 20, "A0s": 20}
            res40, _, _ = camp("Q-F0", roote, adapter_for("Q-F0", "campaign", CL, rv), floors=fl40)
            res40b, _, txt40 = camp("Q-F0", roote, adapter_for("Q-F0", "campaign", CL, rv), floors=fl40,
                                    resume=True, adjudication="selftest: the seat's adjudication")
            ck40, rep40 = ckpt_of(res40b), rep_of(res40b)
            chk("m_sessions: a campaign ending on launch 40 after an adjudicated look-1 pause ends "
                "COMPLETE, not PAUSE: the end look IS look 1 (no new evaluation, no new pause); looks "
                "counted 1 = ceil(40/40)",
                res40["status"] == "PAUSE" and res40b["status"] == "COMPLETE"
                and len(ck40["sessions"]) == 40 and len(ck40["campaign"]["pauses"]) == 1
                and ck40["campaign"]["end_look"]["end_is_look"] == 1
                and ck40["campaign"]["terminal"]["status"] == "COMPLETE" and rep40["looks_count"] == 1
                and "END LOOK campaign-Q-F0: the end look is look 1" in txt40, res40b["status"])
            rooti = fresh("camp_interrupt")
            cut = lambda t, s, n, c: t == "A0" and s == 15 and n == 3
            _, exci, _ = camp("Q-F0", rooti, adapter_for("Q-F0", "campaign", CL, None, cut))
            n_before = len(json.loads((rooti / "ckpt" / "Q-F0_campaign.json").read_text())["sessions"])
            i_bytes = (rooti / "ckpt" / "Q-F0_campaign.json").read_bytes()
            adpj = adapter_for("Q-F0", "campaign", CL)
            _, expj, _ = camp("Q-F0", rooti, adpj, lcs={"A0": 65, "A0s": 32}, resume=True)
            chk("m_sessions: a resume offering another launch-count projection is refused (CHECKPOINT "
                "MISMATCH) before any generation, the checkpoint untouched (finding N4)",
                isinstance(expj, SystemExit) and "CHECKPOINT MISMATCH" in str(expj)
                and "projection" in str(expj) and not adpj.calls
                and (rooti / "ckpt" / "Q-F0_campaign.json").read_bytes() == i_bytes, str(expj)[:70])
            resi, _, txti = camp("Q-F0", rooti, adapter_for("Q-F0", "campaign", CL), resume=True)
            cki = ckpt_of(resi)
            chk("m_sessions: an interrupted campaign resumes skip-only and continues the rotation; its "
                "sessions equal an uninterrupted run's (seconds aside)",
                isinstance(exci, stages._Interrupt) and n_before == 30 and resi["status"] == "COMPLETE"
                and [(r["template"], r["s"]) for r in cki["sessions"]]
                == [(r["template"], r["s"]) for r in ckc["sessions"]]
                and strip_secs(cki["sessions"]) == strip_secs(ckc["sessions"]), (n_before, resi["status"]))
            chk("m_sessions: the resume appends its own provenance entry (stamp, verbatim record, the "
                "sessions it launched and recorded: 30 then 14 -- the session interrupted mid-generation in "
                "the first invocation is counted by neither, finding R5) outside the identity, prints its "
                "PROVENANCE line, and the report copies both entries",
                [e["launched"] for e in cki["provenance"]] == [30, 14]
                and all(e["record"]["adapter"] == testing.STUB_TAG for e in cki["provenance"])
                and rep_of(resi)["provenance"] == cki["provenance"] and "provenance" not in cki["identity"]
                and txti.startswith("PROVENANCE: {\"record\":")
                and [e["launched"] for e in ckc["provenance"]] == [44], [e["launched"] for e in cki["provenance"]])
            # L above the committed n is refused; L equal to it runs (N4)
            adlg = adapter_for("Q-F0", "campaign", {"A0": 2, "A0s": 2})
            rootlg = fresh("camp_l_over_n")
            try:
                camp("Q-F0", rootlg, adlg, floors={"A0": 2, "A0s": 2}, lcs={"A0": 2625, "A0s": 32})
                lg = "ran"
            except ValueError as e:
                lg = str(e)
            reseq, _, _ = camp("Q-F0", fresh("camp_l_eq_n"), adapter_for("Q-F0", "campaign", {"A0": 2, "A0s": 2}),
                               floors={"A0": 2, "A0s": 2}, lcs={"A0": 2624, "A0s": 960})
            chk("m_sessions: a launch count above the committed schedule's n is refused (ValueError) before "
                "any generation or checkpoint; one equal to it (2624 / 960) runs (finding N4)",
                "exceeds the committed schedule" in lg and not adlg.calls and not (rootlg / "ckpt").exists()
                and reseq is not None and reseq["status"] == "COMPLETE"
                and rep_of(reseq)["launch_counts_projection"] == {"A0": 2624, "A0s": 960}, lg[:60])
            # the renders of record through the campaign (N1)
            adrn = adapter_for("Q-F0", "campaign", CL)
            rootrn = fresh("camp_renders")
            _, exrn, _ = camp("Q-F0", rootrn, adrn, identity_extra=xtra(renders_sha16="0" * 16))
            chk("m_sessions: the campaign refuses a renders sha16 that is not the renders of record "
                "(RENDERS MISMATCH) before any generation or checkpoint (finding N1)",
                isinstance(exrn, SystemExit) and "RENDERS MISMATCH" in str(exrn) and not adrn.calls
                and not (rootrn / "ckpt").exists(), str(exrn)[:60])
            # an interrupted finish re-finishes: COMPLETE, and a PI stop not offered again
            rootf = fresh("camp_refinish")
            with cut_at_end(has_end):
                _, excf, _ = camp("Q-F0", rootf, adapter_for("Q-F0", "campaign", CL))
            ckf_mid = json.loads((rootf / "ckpt" / "Q-F0_campaign.json").read_text())
            repf_b = (rootf / "reports" / "Q-F0_campaign_report.json").read_bytes()
            adf = adapter_for("Q-F0", "campaign", CL)
            resf, _, _ = camp("Q-F0", rootf, adf, resume=True)
            chk("m_sessions: a campaign killed after its report was written but before its terminal state "
                "was persisted re-finishes on resume -- nothing launched, COMPLETE persisted, the report "
                "byte-identical",
                isinstance(excf, stages._Interrupt) and ckf_mid["campaign"]["terminal"] is None
                and len(ckf_mid["sessions"]) == 44 and resf is not None and resf["status"] == "COMPLETE"
                and not adf.calls and Path(resf["report"]).read_bytes() == repf_b
                and ckpt_of(resf)["campaign"]["terminal"]["status"] == "COMPLETE",
                (type(excf).__name__, (resf or {}).get("status")))
            resk, _, _ = camp("Q-F0", fresh("camp_cap"), adapter_for("Q-F0", "campaign", CL), cap=1e-9)
            ckk, repk = ckpt_of(resk), rep_of(resk)
            chk("m_sessions: the hour cap is terminal (CAP after the first launch; end look recorded); "
                "the report says the cap is reached and carries no ms of the one contrast session",
                resk["status"] == "CAP" and len(ckk["sessions"]) == 1
                and ckk["campaign"]["terminal"]["status"] == "CAP"
                and ckk["campaign"]["end_look"] is not None and repk["hour_cap_reached"] is True
                and repk["sham_generation_ms"] == 0 and ckk["state"]["hour_cap_ms_used"] > 0,
                resk["status"])
            # forced-phase exclusions on the sham arm: it launches past its floor AND its L
            rx = lambda t, s, n, c: "{Pc} is the answer." if t == "A0s" and s < 3 and n == 1 else None
            small = {"A0": 4, "A0s": 4}
            resx, _, _ = camp("Q-F0", fresh("camp_excl"), adapter_for("Q-F0", "campaign", {"A0": 4, "A0s": 7},
                                                                      rx), floors=small, lcs=small)
            ckx, repx = ckpt_of(resx), rep_of(resx)
            chk("m_sessions: an arm with forced-phase exclusions keeps launching until its DOMAIN count "
                "reaches its floor -- A0s 7 launches (> floor 4 = its L), 3 pre-pick, domain 4; "
                "COMPLETE, no pause",
                resx["status"] == "COMPLETE" and repx["arms"]["A0s"] == {"launched": 7, "domain": 4,
                                                                          "prepick_excluded": 3}
                and repx["arms"]["A0"]["launched"] == 4 and repx["pauses"] == [], repx.get("arms"))
            # the PI's stop: terminal, its text in the checkpoint only, nothing more launched
            rootq = fresh("camp_pistop")
            cutq = lambda t, s, n, c: t == "A0" and s == 5 and n == 3
            _, excq1, _ = camp("Q-F0", rootq, adapter_for("Q-F0", "campaign", CL, None, cutq))
            adq = adapter_for("Q-F0", "campaign", CL)
            pi_text = "PI: stop the unit here (selftest)"
            resps, _, txtps = camp("Q-F0", rootq, adq, resume=True, pi_stop=pi_text)
            ckps, repps = ckpt_of(resps), rep_of(resps)
            _, excps, _ = camp("Q-F0", rootq, adapter_for("Q-F0", "campaign", CL), resume=True)
            _, excp0, _ = camp("Q-F0", fresh("camp_pistop0"), adapter_for("Q-F0", "campaign", CL),
                               resume=True, pi_stop=pi_text)
            chk("m_sessions: a PI stop is terminal (PI-STOP, exit 0) with nothing more launched, its "
                "text in the checkpoint only; a later resume is refused; a PI stop before any launch is "
                "refused",
                isinstance(excq1, stages._Interrupt) and resps["status"] == "PI-STOP" and not adq.calls
                and len(ckps["sessions"]) == 10 and ckps["campaign"]["terminal"]["text"] == pi_text
                and repps["terminal"] == {"status": "PI-STOP", "at_launches": 10}
                and pi_text not in json.dumps(repps) and pi_text not in txtps
                and stages.exit_code(resps["status"]) == 0
                and isinstance(excps, SystemExit) and "CAMPAIGN ENDED" in str(excps)
                and isinstance(excp0, SystemExit) and "PI STOP REFUSED" in str(excp0),
                (resps["status"], len(ckps["sessions"])))
            rootq2 = fresh("camp_pistop_refinish")
            camp("Q-F0", rootq2, adapter_for("Q-F0", "campaign", CL, None, cutq))
            with cut_at_end(has_end):
                _, excq2, _ = camp("Q-F0", rootq2, adapter_for("Q-F0", "campaign", CL), resume=True,
                                   pi_stop=pi_text)
            mid_q = json.loads((rootq2 / "ckpt" / "Q-F0_campaign.json").read_text())
            repq_b = (rootq2 / "reports" / "Q-F0_campaign_report.json").read_bytes()
            _, excq3, _ = camp("Q-F0", rootq2, adapter_for("Q-F0", "campaign", CL), resume=True,
                               pi_stop="PI: a different text (selftest)")
            adq4 = adapter_for("Q-F0", "campaign", CL)
            resq4, _, _ = camp("Q-F0", rootq2, adq4, resume=True)
            chk("m_sessions: the PI's stop is persisted at once and the terminal state last -- killed "
                "before the terminal was persisted, a resume WITHOUT the stop re-finishes PI-STOP "
                "(nothing launched, the report byte-identical); a different stop text is refused",
                isinstance(excq2, stages._Interrupt) and mid_q["campaign"]["pi_stop"] == pi_text
                and mid_q["campaign"]["terminal"] is None
                and isinstance(excq3, SystemExit) and "CHECKPOINT MISMATCH" in str(excq3)
                and resq4 is not None and resq4["status"] == "PI-STOP" and not adq4.calls
                and Path(resq4["report"]).read_bytes() == repq_b
                and ckpt_of(resq4)["campaign"]["terminal"]["text"] == pi_text,
                (type(excq2).__name__, (resq4 or {}).get("status")))
            # a contrast free-phase hair trigger in the campaign: blinded at stop AND at re-invocation
            rootcs = fresh("camp_hair")
            rhc = lambda t, s, n, c: "<|im_end|>" if t == "A0" and s == 1 and n == 7 else None
            rescs, _, txtcs = camp("Q-F0", rootcs, adapter_for("Q-F0", "campaign", CL, rhc))
            ckcs = ckpt_of(rescs)
            evcs = adj_of(rescs)["events"]
            hit_rec = [r for r in ckcs["sessions"] if (r["template"], r["s"]) == ("A0", 1)][0]
            _, excs2, txtcs2 = camp("Q-F0", rootcs, adapter_for("Q-F0", "campaign", CL), resume=True)
            chk("m_sessions: a campaign STOPped by a contrast free-phase trigger announces it by phase "
                "alone, and so does every re-invocation; its excerpt holds the fired round and the pick "
                "its header reveals",
                rescs["status"] == "STOP" and "free phase of a contrast session (A0 s=1)" in txtcs
                and "scaffold" not in txtcs and isinstance(excs2, SystemExit)
                and "free phase of a contrast session (A0 s=1)" in str(excs2)
                and not any("scaffold" in t for t in (str(excs2), txtcs2))
                and [(e["kind"], e["at_launches"]) for e in evcs] == [("hair_trigger", 3)]
                and evcs[0]["rounds"][0]["n"] == 7
                and evcs[0]["picks_revealed"][0]["pick"] == hit_rec["choices"][2]["pick"]
                and "picks_revealed" not in Path(rescs["report"]).read_text(), str(excs2)[:100])
            # a checkpoint name with a roster word is refused at the campaign's start (N10)
            adrw = adapter_for("Q-F0", "campaign", CL)
            rootrw = fresh("camp_roster_name")
            _, exrw, _ = camp("Q-F0", rootrw, adrw, ckpt_path=rootrw / "ckpt" / "Q-F0_campaign.amber-pod.json")
            chk("m_sessions: a campaign checkpoint name naming a roster word is refused at start -- nothing "
                "generated or written",
                isinstance(exrw, SystemExit) and "roster word" in str(exrw) and not adrw.calls
                and not (rootrw / "ckpt").exists() and not (rootrw / "reports").exists(), str(exrw)[:60])
            # an exhausted committed schedule below floor: PAUSE; only a PI stop ends it
            real_lc = stages.load_committed

            def short_sched(unit, wanted, d):
                out = real_lc(unit, wanted, d)
                if wanted and wanted[0][0] == "campaign":
                    out["A0s"]["cells"] = out["A0s"]["cells"][:5]
                    out["A0s"]["n"] = 5
                return out
            rootx = fresh("camp_exhaust")
            with patched(stages, "load_committed", short_sched):
                resx1, _, txtx = camp("Q-F0", rootx, adapter_for("Q-F0", "campaign", {"A0": 4, "A0s": 5}, rx),
                                      floors=small, lcs=small)
                evx = adj_of(resx1)["events"]
                _, excx, _ = camp("Q-F0", rootx, adapter_for("Q-F0", "campaign", {"A0": 4, "A0s": 5}, rx),
                                  floors=small, lcs=small, resume=True, adjudication="seat: continue")
                resx2, _, _ = camp("Q-F0", rootx, adapter_for("Q-F0", "campaign", {"A0": 4, "A0s": 5}, rx),
                                   floors=small, lcs=small, resume=True, pi_stop=pi_text)
            ckx2, repx2 = ckpt_of(resx2), rep_of(resx2)
            chk("m_sessions: an arm that exhausts its committed schedule below floor PAUSEs the unit for "
                "the PI; a resume with only an adjudication is refused, never re-paused; the PI's stop "
                "ends it (PI-STOP)",
                resx1["status"] == "PAUSE" and "exhausted its committed schedule" in txtx
                and isinstance(excx, SystemExit) and "SCHEDULE EXHAUSTED" in str(excx)
                and resx2["status"] == "PI-STOP" and len(ckx2["sessions"]) == 9
                and [p["kind"] for p in repx2["pauses"]] == ["schedule_exhausted"]
                and repx2["pauses"][0]["adjudicated"] is True
                and stages.load_committed is real_lc, (resx1["status"], str(excx)[:40]))
            chk("m_sessions: the schedule-exhausted pause's adjudication excerpt holds the exhausted arm's "
                "counts only (launched 5 of its 5 committed cells, domain 2 below floor 4)",
                [(e["event"], e["kind"]) for e in evx] == [("PAUSE", "schedule_exhausted")]
                and evx[0]["counts"] == {"arm": "A0s", "floor": 4, "schedule_n": 5, "launched": 5,
                                         "domain": 2}
                and "rounds" not in evx[0] and evx[0]["picks_revealed"] == [], evx[0].get("counts"))
            # G-VER in the campaign
            with tampered_runner(bump_text, lambda sc, pc: sc.template == "A0" and sc.s == 3):
                rest, _, txtt = camp("Q-F0", fresh("camp_tamper"), adapter_for("Q-F0", "campaign", CL))
            ckt = ckpt_of(rest)
            chk("m_sessions: G-VER in the campaign -- a tampered A0 s=3 record STOPs the unit; it is "
                "quarantined (verified False), never a session; every recorded session is verified",
                rest["status"] == "STOP" and ckt["stop"]["bar"] == "template_breakage"
                and ckt["stop"]["record"]["verified"] is False
                and ("A0", 3) not in {(r["template"], r["s"]) for r in ckt["sessions"]}
                and len(ckt["sessions"]) == 6 and all(r["verified"] is True for r in ckt["sessions"])
                and stages.run_session_qwen is runner_qwen.run_session_qwen, rest["status"])
            # start refusals: a checkpoint outside ckpt/, a wrong prior stage
            adr = adapter_for("Q-F0", "campaign", CL)
            rootr = fresh("camp_refusals")
            _, exr1, _ = camp("Q-F0", rootr, adr, ckpt_path=rootr / "reports" / "Q-F0_campaign_x.json")
            _, exr2, _ = camp("Q-F0", rootr, adr, prior=prior_time)
            _, exr3, _ = camp("Q-F0", rootr, adr, resume=True, adjudication="seat: nothing is paused")
            resr, _, _ = camp("Q-F0", rootr, adapter_for("Q-F0", "campaign", {"A0": 2, "A0s": 2}),
                              floors={"A0": 2, "A0s": 2}, lcs={"A0": 2, "A0s": 2},
                              ckpt_path=rootr / "ckpt" / "Q-F0_campaign.restart.json")
            chk("m_sessions: a campaign refuses a checkpoint outside <out_root>/ckpt/, a prior that is "
                "not its qualification stage and an adjudication with no pause, before any generation; "
                "a restart name under ckpt/ runs",
                isinstance(exr1, SystemExit) and "CHECKPOINT PATH REFUSED" in str(exr1)
                and isinstance(exr2, SystemExit) and "PRIOR STAGE MISMATCH" in str(exr2) and not adr.calls
                and isinstance(exr3, SystemExit) and "NO PAUSE TO ADJUDICATE" in str(exr3)
                and not (rootr / "ckpt" / "Q-F0_campaign.json").exists()
                and not (rootr / "reports" / "Q-F0_campaign_x.json").exists()
                and resr is not None and resr["status"] == "COMPLETE"
                and Path(resr["checkpoint"]).name == "Q-F0_campaign.restart.json",
                (str(exr1)[:50], str(exr2)[:50]))

            # --- OLMo campaign: pod rules; an ended campaign is never told to restart ----------
            OC = {"A0-OLMo-sft": 24, "A0s-OLMo-sft": 20}
            OL = {"A0-OLMo-sft": 64, "A0s-OLMo-sft": 32}
            rooto = fresh("camp_olmo_pod")
            prior_oq = synthetic_prior(rooto / "ckpt" / "OLMo-sft_qual.json", "OLMo-sft", "qual", "PASS")
            cut_o = lambda t, s, n, c: t == "A0-OLMo-sft" and s == 2 and n == 1
            with olmo_stub_startup():
                with env_pod("podA"):
                    _, exco, _ = camp("OLMo-sft", rooto, adapter_for("OLMo-sft", "campaign", OL, None, cut_o),
                                      floors=OC, lcs=OL, prior=prior_oq)
                opath = rooto / "ckpt" / "OLMo-sft_campaign.json"
                obytes = opath.read_bytes()
                with env_pod("podB"):
                    _, excb, _ = camp("OLMo-sft", rooto, adapter_for("OLMo-sft", "campaign", OL),
                                      floors=OC, lcs=OL, resume=True, prior=prior_oq)
                with env_pod(None):
                    _, excn, _ = camp("OLMo-sft", rooto, adapter_for("OLMo-sft", "campaign", OL),
                                      floors=OC, lcs=OL, resume=True, prior=prior_oq)
                OS = {"A0-OLMo-sft": 2, "A0s-OLMo-sft": 2}
                roote2 = fresh("camp_olmo_ended")
                prior_oq2 = synthetic_prior(roote2 / "ckpt" / "OLMo-sft_qual.json", "OLMo-sft", "qual", "PASS")
                with env_pod("podA"):
                    reso, _, _ = camp("OLMo-sft", roote2, adapter_for("OLMo-sft", "campaign", OS),
                                      floors=OS, lcs=OS, prior=prior_oq2)
                with env_pod("podB"):
                    _, exce, _ = camp("OLMo-sft", roote2, adapter_for("OLMo-sft", "campaign", OS),
                                      floors=OS, lcs=OS, resume=True, prior=prior_oq2)
            chk("m_sessions: an OLMo campaign resume on another pod id is refused (and without one), "
                "its checkpoint untouched",
                isinstance(exco, stages._Interrupt)
                and json.loads(obytes)["identity"]["pod_id"] == "podA"
                and isinstance(excb, SystemExit) and "pod_id" in str(excb)
                and isinstance(excn, SystemExit) and "POD ID ABSENT" in str(excn)
                and opath.read_bytes() == obytes, (str(excb)[:80], str(excn)[:40]))
            chk("m_sessions: an ENDED OLMo campaign resumed on another pod is refused 'CAMPAIGN ENDED' "
                "naming its status, never advised to restart at a new path",
                reso is not None and reso["status"] == "COMPLETE" and isinstance(exce, SystemExit)
                and "CAMPAIGN ENDED" in str(exce) and "(COMPLETE)" in str(exce)
                and "NEW checkpoint" not in str(exce), str(exce)[:80])

        # --- every finish persists its end PENDING first (finding R1) ------------------------
        @contextlib.contextmanager
        def frozen():
            # selftest only: a fixed clock in both runners and a fixed provenance stamp, so a
            # re-finish's outputs compare byte for byte with an uninterrupted run's
            tick = {"t": 0.0}

            def pc():
                tick["t"] += 0.25
                return tick["t"]
            ns = types.SimpleNamespace(perf_counter=pc)
            with patched(runner_qwen, "time", ns), patched(runner_olmo, "time", ns), \
                    patched(resume, "utc_stamp", lambda: "2026-10-06T00:00:00Z"):
                yield

        def kill_before_outputs():
            # stages' output writer wrapped (selftest only, restored on exit): its first call --
            # the report, written after the end is pending -- dies
            real = stages._write_json
            state = {"n": 0}

            def w(path, obj):
                if state["n"] == 0:
                    state["n"] += 1
                    raise stages._Interrupt("selftest: killed after the end was pending, before any output")
                real(path, obj)
            return patched(stages, "_write_json", w)

        def outputs_of(root: Path, stem: str) -> tuple:
            fs = (root / "reports" / f"{stem}_report.json", root / "reports" / f"{stem}_reads.json",
                  root / "ckpt" / f"{stem}_adjudication.json", root / "gates" / "Q-F0_G-ID.json")
            return tuple(f.read_bytes() if f.is_file() else None for f in fs)

        def gate_run(unit, counts, rule=None, tamper=None, olmo=False):
            def run(root, **kw):
                ad = adapter_for(unit, "time", counts, rule)
                with contextlib.ExitStack() as st:
                    st.enter_context(gates_at(base / "no-gates"))
                    if tamper is not None:
                        st.enter_context(tampered_runner(*tamper))
                    if olmo:
                        st.enter_context(olmo_stub_startup())
                    return gate(unit, "time", counts, root, ad, **kw), ad
            return run

        def gid_run(root, **kw):
            ad = adapter_for("Q-F0", "id", {"A0s": 16})
            with gates_at(root / "gates"):
                return gid(root, ad, prior_time, **kw), ad

        def camp_run(rule):
            def run(root, **kw):
                ad = adapter_for("Q-F0", "campaign", CL, rule)
                with gates_at(base / "no-gates"):
                    return camp("Q-F0", root, ad, **kw), ad
            return run

        R1_CASES = (
            ("hair", "a contrast free-phase hair-trigger STOP", "Q-F0_time", gate_run("Q-F0", QT, rh), "STOP",
             (None, "podB"), False),
            ("gver", "a G-VER STOP", "Q-F0_time",
             gate_run("Q-F0", QT, tamper=(bump_text, lambda sc, pc: sc.template == "A0s")), "STOP",
             (None, "podB"), False),
            ("bar", "a stage-end bar STOP", "Q-F0_time", gate_run("Q-F0", QT, r3), "STOP", (None, "podB"), False),
            ("olmo", "an OLMo G-TIME PAUSE", "OLMo-sft_time", gate_run("OLMo-sft", OT, rp, olmo=True), "PAUSE",
             ("podO", "podO2"), False),
            ("camp", "a campaign hair-trigger STOP", "Q-F0_campaign", camp_run(rhc), "STOP", (None, "podB"),
             False),
            ("pass", "a PASS (a stale excerpt planted)", "Q-F0_time", gate_run("Q-F0", QT), "PASS",
             (None, "podB"), True),
            ("gid", "G-ID's PASS (its artifact)", "Q-F0_id", gid_run, "PASS", (None, "podB"), False))
        r1 = {}
        for tag, label, stem, run, ended, pods, plant in R1_CASES:
            ref_root = fresh(f"r1_{tag}_ref")
            with env_pod(pods[0]), frozen():
                (res0, exc0, _), _ = run(ref_root)
            ref = outputs_of(ref_root, stem)
            got = {"ref": res0 is not None and res0["status"] == ended and exc0 is None and ref[0] is not None}
            for kill in ("before the outputs", "after the outputs"):
                for how, pod, kw in (("same pod, plain", pods[0], {}), ("another pod, --resume", pods[1],
                                                                      {"resume": True})):
                    root = fresh(f"r1_{tag}_{kill.split()[0]}_{how.split(',')[0].replace(' ', '_')}")
                    with env_pod(pods[0]), frozen(), \
                            (kill_before_outputs() if kill.startswith("before") else cut_at_end(has_end)):
                        (_, exk, _), _ = run(root)
                    cp = root / "ckpt" / f"{stem}.json"
                    mid = json.loads(cp.read_text(encoding="utf-8"))
                    mid_out = outputs_of(root, stem)
                    stale = cp.with_name(f"{stem}_adjudication.json")
                    if plant:
                        stale.write_text('{"selftest": "a stale excerpt"}\n', encoding="utf-8")
                    with env_pod(pod), frozen():
                        (resr, exr, txtr), adr = run(root, **kw)
                    fin = json.loads(cp.read_text(encoding="utf-8"))
                    got[f"{kill} / {how}"] = (
                        isinstance(exk, stages._Interrupt) and "end_pending" in mid
                        and resume.ended_status(mid) is None
                        and (mid_out[0] is None if kill.startswith("before") else mid_out == ref)
                        and exr is None and resr is not None and resr["status"] == ended and not adr.calls
                        and outputs_of(root, stem) == ref and resume.ended_status(fin) == ended
                        and "end_pending" not in fin and f"RE-FINISH " in txtr
                        and not list(cp.parent.glob("*.podchange-*"))
                        and (not plant or not stale.exists()))
            r1[label] = got
        chk("m_sessions: every finish writes its end PENDING with every session before any output (finding R1) "
            "-- a hair-trigger STOP, a G-VER STOP, a stage-end bar STOP, an OLMo PAUSE, a campaign STOP, a "
            "PASS and G-ID's PASS, each killed before its outputs and after them: re-invoked plainly on the "
            "same pod and with --resume on another pod, it re-finishes -- zero generate calls, no set-aside "
            "(finding R2), report, reads, excerpt (and artifact) byte-identical to an uninterrupted run's, "
            "the end persisted; a stale excerpt is removed by the PASS re-finish",
            all(all(v.values()) for v in r1.values()),
            {k: [n for n, ok in v.items() if not ok] for k, v in r1.items() if not all(v.values())})

        # --- ruling (h): at every G-TIME stage the contrast session's forced rounds reach stdout and the report as counts only --
        def blind_outputs(res, txt, root):
            # stdout with the run's root normalised; the report's bytes; the reads with the
            # contrast session's LAST forced response masked (its bytes are the one thing a
            # different class must change, and m:280's mandated read shows them) and the
            # piece offsets the mask moves dropped
            rd = json.loads(res["reads"].read_text(encoding="utf-8"))
            for r in rd["sessions"]:
                if r["contrast"] and r["rounds"]:
                    g = [p for p in r["pieces"] if p["kind"] == "generation"][-1]
                    r["transcript"] = r["transcript"][:g["start"]] + "<GEN>" + r["transcript"][g["end"]:]
                    r["rounds"][-1]["text"] = "<GEN>"
                    for p in r["pieces"]:
                        p.pop("start")
                        p.pop("end")
            return (txt.replace(str(root), "<ROOT>"), res["report"].read_bytes(), json.dumps(rd, sort_keys=True))

        def at_n(text, tpl, n_at):
            return lambda t, s, n, c: text if t == tpl and n == n_at else None

        H_CASES = {"qwen": ("Q-F0", QT, "A0", {"v2": "Config choice one.", "echo": "{COMMON}",
                                               "content": "* * *", "lexical": "{Pc} is the answer."}),
                   "olmo": ("OLMo-sft", OT, "A0-OLMo-sft", {"audit": "Config choice one.", "echo": "{COMMON}",
                                                            "lexical": "{Pc}."})}
        hview, hcls, hblk = {}, {}, {}
        for sub_, (unit_, counts_, ctpl, texts_) in H_CASES.items():
            for cls_, text_ in texts_.items():
                root_ = fresh(f"h_{sub_}_{cls_}")
                with env_pod("podH" if sub_ == "olmo" else None), frozen():
                    (res_, _, txt_), _ = gate_run(unit_, counts_, at_n(text_, ctpl, 2), olmo=sub_ == "olmo")(root_)
                con_ = [r for r in ckpt_of(res_)["sessions"] if r["template"] == ctpl][0]
                exc_ = con_["exclusion"] or {}
                hcls[(sub_, cls_)] = (res_["status"], exc_.get("class"), exc_.get("phase"),
                                      sum(r["phase"] == "forced" for r in con_["rounds"]))
                hview[(sub_, cls_)] = blind_outputs(res_, txt_, root_)
                hblk[(sub_, cls_)] = rep_of(res_)["stage_report"]["templates"][ctpl]
        chk("m_sessions: ruling (h) -- G-TIME stub runs whose contrast session differs ONLY in the class of its "
            "forced exclusion at round 2 (Qwen v2/echo/content/lexical, OLMo AuditSpec/echo/lexical; each class "
            "recorded in the checkpoint) give byte-identical stdout (the line by phase alone, "
            "'excluded:excluded@forced'), report and reads (outside the excluded round's response bytes, which "
            "m:280's mandated read shows); the report's contrast block is the counts only",
            all(hcls[(s_, c_)] == ("PASS", c_, "forced", 2) for s_, v in H_CASES.items() for c_ in v[3])
            and all(len({hview[(s_, c_)] for c_ in v[3]}) == 1 for s_, v in H_CASES.items())
            and "time A0 s=0 excluded:excluded@forced" in hview[("qwen", "v2")][0].splitlines()
            and "time A0-OLMo-sft s=0 excluded:excluded@forced" in hview[("olmo", "audit")][0].splitlines()
            and all(b == {"contrast": True, "sessions": 1, "per_session": [
                {"s": 0, "forced_rounds_generated": 2, "excluded_at_forced": True}],
                "free_rounds": hblk[("qwen", "v2")]["free_rounds"]} for b in hblk.values())
            and not any(w in hview[k][0] for k in hview
                        for w in ("audit@forced", "echo@forced", "content@forced", "lexical@forced")),
            hcls)
        cnt_rules = {"round 1": at_n("Config choice one.", "A0", 1), "round 3": at_n("{COMMON}", "A0", 3),
                     "clean": None, "free lexical": at_n("{Pc} it is.", "A0", 7)}
        cview, cper = {}, {}
        for nm, rule_ in cnt_rules.items():
            root_ = fresh(f"h_count_{nm.replace(' ', '_')}")
            with env_pod(None), frozen():
                (res_, _, txt_), _ = gate_run("Q-F0", QT, rule_)(root_)
            cview[nm] = (txt_.replace(str(root_), "<ROOT>"), res_["report"].read_bytes(),
                         res_["reads"].read_bytes())
            cper[nm] = rep_of(res_)["stage_report"]["templates"]["A0"]["per_session"]
        line_of = {nm: [ln for ln in v[0].splitlines() if ln.startswith("time A0 ")] for nm, v in cview.items()}
        chk("m_sessions: ruling (h) -- G-TIME runs differing in the contrast session's rounds generated / "
            "excluded give exactly the permitted counts (a round-1 exclusion 1/yes, a round-3 one 3/yes, clean 4/no, "
            "a free-round exclusion 4/no); the round-1 and round-3 runs print the same stdout; a free-round "
            "exclusion's report and reads equal the clean run's (its line excluded@free, m:263)",
            cper == {"round 1": [{"s": 0, "forced_rounds_generated": 1, "excluded_at_forced": True}],
                     "round 3": [{"s": 0, "forced_rounds_generated": 3, "excluded_at_forced": True}],
                     "clean": [{"s": 0, "forced_rounds_generated": 4, "excluded_at_forced": False}],
                     "free lexical": [{"s": 0, "forced_rounds_generated": 4, "excluded_at_forced": False}]}
            and cview["round 1"][0] == cview["round 3"][0] and cview["round 1"][1] != cview["round 3"][1]
            and cview["clean"][1:] == cview["free lexical"][1:]
            and line_of == {"round 1": ["time A0 s=0 excluded:excluded@forced"],
                            "round 3": ["time A0 s=0 excluded:excluded@forced"],
                            "clean": ["time A0 s=0 valid"], "free lexical": ["time A0 s=0 excluded:excluded@free"]},
            (cper, line_of))
        root_ = fresh("h_forced_hair")
        with env_pod(None), frozen():
            (res_, _, txt_), _ = gate_run("Q-F0", QT, at_n("<|im_end|>", "A0", 3))(root_)
        rep_h = rep_of(res_)
        rd_h = [r for r in json.loads(res_["reads"].read_text())["sessions"] if r["contrast"]][0]
        chk("m_sessions: ruling (h) with m:318 exception (1) kept as built -- a forced-phase hair trigger on the "
            "G-TIME contrast session (a scaffold string, also a v2 claim) STOPs the stage; its session line is "
            "by phase alone (no 'audit@forced'), the announcement names the trigger (BAR scaffold_absorption "
            "FIRED template=A0 phase=forced; the report's blinded stop block), the report's contrast block is "
            "counts only (3 rounds, excluded) and the read carries no hair-trigger name or class",
            res_["status"] == "STOP" and "time A0 s=0 excluded:excluded@forced" in txt_.splitlines()
            and "audit@forced" not in txt_ and "BAR scaffold_absorption FIRED template=A0 phase=forced" in txt_
            and rep_h["stop"] == {"bar": "scaffold_absorption", "template": "A0", "s": 0, "phase": "forced"}
            and rep_h["stage_report"]["templates"]["A0"]["per_session"]
            == [{"s": 0, "forced_rounds_generated": 3, "excluded_at_forced": True}]
            and "hair_triggers" not in rd_h and "exclusion" not in rd_h
            and all(set(x) == {"phase", "ri", "n", "text"} for x in rd_h["rounds"])
            and ckpt_of(res_)["sessions"][0]["exclusion"]["class"] == "v2", txt_.splitlines()[-6:-4])

        with gates_at(base / "no-gates"):
            # an OLMo campaign's pending end re-finishes on another pod (its checkpoint carries its
            # pod id: a write there is admitted only when it records no session)
            OS2 = {"A0-OLMo-sft": 2, "A0s-OLMo-sft": 2}
            rootoc = fresh("r1_olmo_campaign_pod")
            prior_oc = synthetic_prior(rootoc / "ckpt" / "OLMo-sft_qual.json", "OLMo-sft", "qual", "PASS")
            with olmo_stub_startup():
                with env_pod("podA"), kill_before_outputs():
                    _, exoc, _ = camp("OLMo-sft", rootoc, adapter_for("OLMo-sft", "campaign", OS2),
                                      floors=OS2, lcs=OS2, prior=prior_oc)
                with env_pod("podB"):
                    adoc = adapter_for("OLMo-sft", "campaign", OS2)
                    resoc, exoc2, txtoc = camp("OLMo-sft", rootoc, adoc, floors=OS2, lcs=OS2, prior=prior_oc,
                                               resume=True)
            ckoc = json.loads((rootoc / "ckpt" / "OLMo-sft_campaign.json").read_text(encoding="utf-8"))
            chk("m_sessions: an OLMo campaign killed with its end pending re-finishes on ANOTHER pod -- nothing "
                "launched, COMPLETE persisted, the identity still naming its own pod (no splice: the write "
                "records no session)",
                isinstance(exoc, stages._Interrupt) and exoc2 is None and resoc is not None
                and resoc["status"] == "COMPLETE" and not adoc.calls
                and ckoc["identity"]["pod_id"] == "podA" and ckoc["state"]["pod_id_seen"] == "podB"
                and ckoc["campaign"]["terminal"]["status"] == "COMPLETE" and "end_pending" not in ckoc
                and [e["launched"] for e in ckoc["provenance"]] == [4, 0], (str(exoc2)[:80], txtoc[-200:]))

            # --- a look pause killed with its end pending; a ruling offered with it; a shown pause (R6)
            root6 = fresh("r6_pause")
            cp6 = root6 / "ckpt" / "Q-F0_campaign.json"
            rep6 = root6 / "reports" / "Q-F0_campaign_report.json"
            adj6 = root6 / "ckpt" / "Q-F0_campaign_adjudication.json"
            with kill_before_outputs():
                _, ex6, _ = camp("Q-F0", root6, adapter_for("Q-F0", "campaign", CL, rv))
            mid6 = json.loads(cp6.read_text(encoding="utf-8"))
            no_rep6 = not rep6.exists()
            ad6 = adapter_for("Q-F0", "campaign", CL, rv)
            res6, ex6b, txt6 = camp("Q-F0", root6, ad6, resume=True, adjudication="seat: continue (selftest)")
            fin6 = json.loads(cp6.read_text(encoding="utf-8"))
            rep_b, adj_b, cp_b = rep6.read_bytes(), adj6.read_bytes(), cp6.read_bytes()
            chk("m_sessions: a campaign look pause killed after its end was pending and before its report: an "
                "invocation offering the seat's adjudication re-finishes the pause (nothing launched, report and "
                "excerpt written, the pause persisted UNadjudicated) and then refuses NOT APPLIED -- Code never "
                "applies a ruling to an end it has not shown",
                isinstance(ex6, stages._Interrupt) and "end_pending" in mid6 and no_rep6
                and mid6["end_pending"]["pause"]["kind"] == "look"
                and isinstance(ex6b, SystemExit) and "NOT APPLIED" in str(ex6b) and not ad6.calls
                and [(p["kind"], p["at_launches"], p["adjudication"]) for p in fin6["campaign"]["pauses"]]
                == [("look", 40, None)] and "end_pending" not in fin6 and adj6.is_file()
                and json.loads(rep_b)["status"] == "PAUSE", str(ex6b)[:90])
            rep6.unlink()
            adj6.unlink()
            ad7 = adapter_for("Q-F0", "campaign", CL, rv)
            res7, ex7, txt7 = camp("Q-F0", root6, ad7)
            ad8 = adapter_for("Q-F0", "campaign", CL, rv)
            res8, ex8, _ = camp("Q-F0", root6, ad8, resume=True)
            chk("m_sessions: a paused campaign whose report is missing, re-invoked PLAINLY with no ruling, "
                "re-derives its report and excerpt byte-identical from the checkpoint (finding R6) -- PAUSE, "
                "exit 3, nothing launched, no checkpoint change; with --resume likewise",
                ex7 is None and res7 is not None and res7["status"] == "PAUSE" and stages.exit_code("PAUSE") == 3
                and not ad7.calls and rep6.read_bytes() == rep_b and adj6.read_bytes() == adj_b
                and ex8 is None and res8 is not None and res8["status"] == "PAUSE" and not ad8.calls
                and cp6.read_bytes() == cp_b and "is paused (look, at 40 launches)" in txt7,
                (str(ex7)[:80], str(ex8)[:80]))

            # --- reports named after the checkpoint (R10) ---------------------------------------
            S2 = {"A0": 2, "A0s": 2}
            root10 = fresh("r10_restart")
            res10a, _, _ = camp("Q-F0", root10, adapter_for("Q-F0", "campaign", S2), floors=S2, lcs=S2)
            old10 = Path(res10a["report"]).read_bytes()
            res10b, _, _ = camp("Q-F0", root10, adapter_for("Q-F0", "campaign", S2), floors=S2, lcs=S2,
                                ckpt_path=root10 / "ckpt" / "Q-F0_campaign.podB.json")
            res10g, _, _ = gate("Q-F0", "time", QT, root10, adapter_for("Q-F0", "time", QT))
            old10g = Path(res10g["report"]).read_bytes()
            res10h, _, _ = gate("Q-F0", "time", QT, root10, adapter_for("Q-F0", "time", QT),
                                ckpt_path=root10 / "ckpt" / "Q-F0_time.podB.json")
            chk("m_sessions: a campaign (and a gate stage) restarted at a new checkpoint path writes its report "
                "and reads under that checkpoint's stem and leaves the old checkpoint's report untouched "
                "(finding R10)",
                res10a["status"] == res10b["status"] == "COMPLETE"
                and Path(res10a["report"]).name == "Q-F0_campaign_report.json"
                and Path(res10b["report"]).name == "Q-F0_campaign.podB_report.json"
                and (root10 / "reports" / "Q-F0_campaign_report.json").read_bytes() == old10
                and rep_of(res10b)["files"]["checkpoint"] == "ckpt/Q-F0_campaign.podB.json"
                and Path(res10h["report"]).name == "Q-F0_time.podB_report.json"
                and Path(res10h["reads"]).name == "Q-F0_time.podB_reads.json"
                and (root10 / "reports" / "Q-F0_time_report.json").read_bytes() == old10g,
                (Path(res10b["report"]).name, Path(res10h["reads"]).name))

        # --- the G-ID artifact's proposal where the qualification and the campaign take it (R3) ------
        root3 = fresh("r3_artifact")
        with gates_at(root3 / "gates"):
            (root3 / "gates").mkdir(parents=True, exist_ok=True)
            guard.gid_artifact_path("Q-F0").write_text(json.dumps(
                {"verdict": "FAIL", "identity": {"proposal_sha256": "7" * 64}, "provenance": []}), encoding="utf-8")
            readopt = xtra(prior_proposal_sha256s=["7" * 64])
            S2 = {"A0": 2, "A0s": 2}
            adq3 = adapter_for("Q-F0", "qual", QQ)
            _, exq3, _ = gate("Q-F0", "qual", QQ, fresh("r3_qual_other"), adq3, prior_ckpt=prior_time)
            resq3, exq3b, _ = gate("Q-F0", "qual", QQ, fresh("r3_qual_readopt"), adapter_for("Q-F0", "qual", QQ),
                                   prior_ckpt=prior_time, identity_extra=readopt)
            adc3 = adapter_for("Q-F0", "campaign", S2)
            rootc3 = fresh("r3_camp_other")
            _, exc3, _ = camp("Q-F0", rootc3, adc3, floors=S2, lcs=S2)
            resc3, exc3b, _ = camp("Q-F0", fresh("r3_camp_readopt"), adapter_for("Q-F0", "campaign", S2),
                                   floors=S2, lcs=S2, identity_extra=readopt)
        chk("m_sessions: a G-ID artifact under another proposal licenses neither the qualification nor the "
            "campaign's path (refused before any generation or checkpoint, finding R3); under a proposal the "
            "lock re-adopts (prior_proposal_sha256s) both run",
            isinstance(exq3, SystemExit) and "G-ID ARTIFACT UNDER ANOTHER PROPOSAL" in str(exq3) and not adq3.calls
            and exq3b is None and resq3 is not None and resq3["status"] == "PASS"
            and isinstance(exc3, SystemExit) and "G-ID ARTIFACT UNDER ANOTHER PROPOSAL" in str(exc3)
            and not adc3.calls and not (rootc3 / "ckpt").exists()
            and exc3b is None and resc3 is not None and resc3["status"] == "COMPLETE",
            (str(exq3)[:70], str(exc3)[:70]))

        # --- an announced end is never lifted; a re-finish announces it again (round-3 verification) ---
        @contextlib.contextmanager
        def kill_as_pending_lands():
            # resume.write_checkpoint wrapped (selftest only, restored on exit): the first write
            # carrying an end pending dies BEFORE anything is written -- a process killed between a
            # fired look and its pending end
            real = resume.write_checkpoint
            state = {"cut": 0}

            def w(path, ck):
                if state["cut"] == 0 and "end_pending" in ck:
                    state["cut"] += 1
                    raise stages._Interrupt("selftest: killed as the pending end was being written")
                real(path, ck)
            with patched(resume, "write_checkpoint", w):
                yield

        @contextlib.contextmanager
        def stdout_at_persist():
            # resume.persist_end wrapped (selftest only, restored on exit): what the captured
            # stdout carried when each end was persisted
            real = resume.persist_end
            seen: list[str] = []

            def p(path, final):
                seen.append(sys.stdout.getvalue())
                real(path, final)
            with patched(resume, "persist_end", p):
                yield seen

        def announced(text: str) -> list[str]:
            return [ln for ln in text.splitlines() if ln.startswith(("BAR ", "STOP ", "PAUSE ", "END LOOK "))]

        def fired_n(text: str) -> int:
            return sum(" FIRED " in ln for ln in text.splitlines())

        with gates_at(base / "no-gates"):
            rootw = fresh("lw_kill_at_pending")
            cpw = rootw / "ckpt" / "Q-F0_campaign.json"
            with kill_as_pending_lands():
                _, exw, txtw = camp("Q-F0", rootw, adapter_for("Q-F0", "campaign", CL, rv))
            midw = json.loads(cpw.read_text(encoding="utf-8"))
            no_rep_w = not (rootw / "reports" / "Q-F0_campaign_report.json").exists()
            adw = adapter_for("Q-F0", "campaign", CL, rv)
            with stdout_at_persist() as seenw:
                resw, exw2, txtw2 = camp("Q-F0", rootw, adw, resume=True)
            finw = ckpt_of(resw) if resw else {}
            lkw = finw["looks"][0]["result"] if finw.get("looks") else {}
            chk("m_sessions: a campaign whose look fires, killed as its pending end is written: stdout carries no "
                "FIRED line and nothing of the look is on disk (39 sessions, no look, no end, no report); the "
                "re-invocation launches only the 40th session, the look fires again and its bar messages print "
                "once, after the end is persisted (an announced PAUSE is never lifted by a kill in the window)",
                isinstance(exw, stages._Interrupt) and fired_n(txtw) == 0 and announced(txtw) == []
                and len(midw["sessions"]) == 39 and midw["looks"] == [] and "end_pending" not in midw
                and resume.ended_status(midw) is None and no_rep_w
                and exw2 is None and resw is not None and resw["status"] == "PAUSE"
                and [e["launched"] for e in finw["provenance"]] == [39, 1]
                and lkw.get("fired") is True and fired_n(txtw2) == 1
                and announced(txtw2) == [r["message"] for r in lkw["results"]]
                and len(seenw) == 1 and announced(seenw[0]) == [],
                (type(exw).__name__, fired_n(txtw), len(midw["sessions"]), (resw or {}).get("status")))
            roots = fresh("lw_silent_look")
            cut41 = lambda t, s, n, c: t == "A0" and s == 20 and n == 2        # the 41st launch
            _, exs, txts = camp("Q-F0", roots, adapter_for("Q-F0", "campaign", CL, None, cut41))
            cks = json.loads((roots / "ckpt" / "Q-F0_campaign.json").read_text(encoding="utf-8"))
            lks = cks["looks"][0]["result"] if cks["looks"] else {}
            chk("m_sessions: a SILENT look still prints at once -- killed inside the 41st session, stdout already "
                "ends with look 1's three bar messages right after the 40th session's line, and the look is on "
                "disk with its session",
                isinstance(exs, stages._Interrupt) and len(cks["sessions"]) == 40 and len(cks["looks"]) == 1
                and lks.get("fired") is False and fired_n(txts) == 0
                and txts.splitlines()[-4:] == ["campaign A0s s=19 valid"] + [r["message"] for r in lks["results"]],
                txts.splitlines()[-4:-3])

        # every campaign end kind: the uninterrupted run vs the same run killed with its end pending
        # (before any output) and re-finished plainly
        adj_lw = "seat: continue (selftest)"
        LW_CASES = (
            ("a look PAUSE", "PAUSE", rv, CL, {}, [], {}, None),
            ("an end-look PAUSE", "PAUSE", rv, CL, {}, [{}], {"resume": True, "adjudication": adj_lw}, None),
            ("a COMPLETE ending on look 1 (END LOOK)", "COMPLETE", rv, CL, {"floors": fl40}, [{}],
             {"resume": True, "adjudication": adj_lw}, None),
            ("a COMPLETE with its end look", "COMPLETE", None, CL, {}, [], {}, None),
            ("a schedule-exhausted PAUSE", "PAUSE", rx, {"A0": 4, "A0s": 5}, {"floors": small, "lcs": small}, [],
             {}, lambda: patched(stages, "load_committed", short_sched)),
            ("a hair-trigger STOP", "STOP", rhc, CL, {}, [], {}, None))
        lw: dict[str, bool] = {}
        lw_txt: dict[str, tuple] = {}
        for k, (label, want_st, rule, counts, ckw, before, last, patch) in enumerate(LW_CASES):
            runs = {}
            for mode in ("ref", "kill"):
                root = fresh(f"lw_case{k}_{mode}")
                with gates_at(base / "no-gates"), (patch() if patch else contextlib.nullcontext()):
                    for kw in before:
                        camp("Q-F0", root, adapter_for("Q-F0", "campaign", counts, rule), **ckw, **kw)
                    with (kill_before_outputs() if mode == "kill" else contextlib.nullcontext()), \
                            stdout_at_persist() as seen:
                        runs[mode] = camp("Q-F0", root, adapter_for("Q-F0", "campaign", counts, rule),
                                          **ckw, **last) + (seen,)
                    if mode == "kill":
                        adr = adapter_for("Q-F0", "campaign", counts, rule)
                        with stdout_at_persist() as seen_re:
                            runs["re"] = camp("Q-F0", root, adr, **ckw) + (seen_re, adr)
            (r_res, r_exc, r_txt, r_seen), (_, k_exc, k_txt, _) = runs["ref"], runs["kill"]
            re_res, re_exc, re_txt, re_seen, re_ad = runs["re"]
            lw_txt[label] = (r_txt, k_txt, re_txt)
            lw[label] = (r_exc is None and r_res is not None and r_res["status"] == want_st
                         and isinstance(k_exc, stages._Interrupt)
                         and re_exc is None and re_res is not None and re_res["status"] == want_st
                         and not re_ad.calls and "RE-FINISH campaign-Q-F0" in re_txt
                         and announced(re_txt) != []
                         and announced(k_txt) + announced(re_txt) == announced(r_txt)
                         and len(r_seen) == 1 and announced(r_seen[0]) == announced(k_txt)
                         and len(re_seen) == 1 and announced(re_seen[0]) == [])
        chk("m_sessions: every campaign end -- a look PAUSE, an end-look PAUSE, a COMPLETE ending on look 1, a "
            "COMPLETE with its end look, a schedule-exhausted PAUSE, a hair-trigger STOP -- announces itself only "
            "after its end is persisted; killed with the end pending, the plain re-invocation re-finishes (zero "
            "generate calls) and prints the same announcement: the lines the killed run printed plus the "
            "re-finish's equal the uninterrupted run's, nothing twice, nothing lost",
            all(lw.values()), [n for n, ok in lw.items() if not ok])
        r_look, k_look, re_look = lw_txt["a look PAUSE"]
        chk("m_sessions: a fired look prints its bar messages exactly once per finish -- uninterrupted, once, "
            "after the end is persisted; killed with the end pending, none before the kill and once in the "
            "re-finish, after its RE-FINISH line",
            fired_n(r_look) == 1 and fired_n(k_look) == 0 and fired_n(re_look) == 1
            and re_look.index("RE-FINISH ") < re_look.index(" FIRED ")
            < re_look.index("STAGE campaign-Q-F0 PAUSE"), (fired_n(r_look), fired_n(k_look), fired_n(re_look)))
        r_el, _, re_el = lw_txt["a COMPLETE ending on look 1 (END LOOK)"]
        el_line = "END LOOK campaign-Q-F0: the end look is look 1 (at 40 launches)"
        chk("m_sessions: a campaign ending on look 1 (adjudicated) announces END LOOK at its finish AND at its "
            "re-finish -- never look 1's bar messages again (that FIRED bar is the seat's, already adjudicated)",
            announced(r_el) == [el_line] and announced(re_el) == [el_line] and fired_n(re_el) == 0,
            announced(re_el)[:1])

        # --- a path mismatch with an end pending re-finishes; with none it is refused (round-3 verification) --
        rootpm = fresh("pm_gid")
        S2 = {"A0": 2, "A0s": 2}
        cutq = lambda t, s, n, c: t == "A0s" and s == 3 and n == 2
        cutc = lambda t, s, n, c: t == "A0" and s == 1 and n == 2
        with gates_at(rootpm / "gates"):
            resg, _, _ = gid(rootpm, adapter_for("Q-F0", "id", {"A0s": 16}), prior_time)
            bid_x = resume.backend_identifier(adapter_for("Q-F0", "qual", QQ).provenance())
            pm: dict[str, bool] = {}
            # the lock fixes cached (backend X's G-ID licence); re-invoked on Y, whose licence gives uncached
            rq = fresh("pm_qual")
            with kill_before_outputs():
                _, exk, _ = gate("Q-F0", "qual", QQ, rq, adapter_for("Q-F0", "qual", QQ), lp="cached",
                                 prior_ckpt=prior_time)
            ady = on_backend_y(adapter_for("Q-F0", "qual", QQ))
            resy, exy, txty = gate("Q-F0", "qual", QQ, rq, ady, lp="cached", prior_ckpt=prior_time)
            cky = ckpt_of(resy) if resy else {}
            pm["qualification: cached lock, uncached licence"] = (
                resg is not None and resg["status"] == "PASS"
                and isinstance(exk, stages._Interrupt) and exy is None and resy is not None
                and resy["status"] == "PASS" and not ady.calls
                and txty.startswith("PATH (G-F0m-Qwen): the lock fixes cached; this backend's licence gives "
                                    "uncached")
                and "RE-FINISH G-F0m-Qwen" in txty and "STAGE G-F0m-Qwen PASS path=cached" in txty
                and cky["stage_end"]["status"] == "PASS" and "end_pending" not in cky
                and cky["identity"]["path"] == "cached" and cky["identity"]["backend_identifier"] == bid_x
                and [e["launched"] for e in cky["provenance"]] == [24, 0])
            rc = fresh("pm_camp")
            with kill_before_outputs():
                _, exkc, _ = camp("Q-F0", rc, adapter_for("Q-F0", "campaign", S2), floors=S2, lcs=S2, lp="cached")
            adyc = on_backend_y(adapter_for("Q-F0", "campaign", S2))
            resyc, exyc, txtyc = camp("Q-F0", rc, adyc, floors=S2, lcs=S2, lp="cached")
            ckyc = ckpt_of(resyc) if resyc else {}
            pm["campaign: cached lock, uncached licence"] = (
                isinstance(exkc, stages._Interrupt) and exyc is None and resyc is not None
                and resyc["status"] == "COMPLETE" and not adyc.calls
                and txtyc.startswith("PATH (campaign-Q-F0): the lock fixes cached; this backend's licence gives "
                                     "uncached")
                and "RE-FINISH campaign-Q-F0" in txtyc and "STAGE campaign-Q-F0 COMPLETE path=cached" in txtyc
                and ckyc["campaign"]["terminal"]["status"] == "COMPLETE" and "end_pending" not in ckyc
                and ckyc["identity"]["path"] == "cached" and [e["launched"] for e in ckyc["provenance"]] == [4, 0])
            # the other direction: locked uncached on Y, re-invoked on X, whose licence gives cached
            ru = fresh("pm_qual_rev")
            with kill_before_outputs():
                _, exku, _ = gate("Q-F0", "qual", QQ, ru, on_backend_y(adapter_for("Q-F0", "qual", QQ)),
                                  lp="uncached", prior_ckpt=prior_time)
            adx = adapter_for("Q-F0", "qual", QQ)
            resx_, exx_, txtx_ = gate("Q-F0", "qual", QQ, ru, adx, lp="uncached", prior_ckpt=prior_time)
            pm["qualification: uncached lock, cached licence"] = (
                isinstance(exku, stages._Interrupt) and exx_ is None and resx_ is not None
                and resx_["status"] == "PASS" and not adx.calls
                and txtx_.startswith("PATH (G-F0m-Qwen): the lock fixes uncached; this backend's licence gives "
                                     "cached")
                and "STAGE G-F0m-Qwen PASS path=uncached" in txtx_
                and ckpt_of(resx_)["stage_end"]["status"] == "PASS")
            chk("m_sessions: a Qwen stage with an end pending, re-invoked on a backend whose G-ID licence now gives "
                "the other path, RE-FINISHES under its locked path -- the qualification and the campaign locked "
                "cached (licence uncached on backend Y), and a qualification locked uncached (licence cached): a "
                "PATH line, zero generate calls, the end persisted, its identity's path and backend the recorded "
                "ones, a 0-launch provenance entry",
                all(pm.values()), [n for n, ok in pm.items() if not ok])
            # the same mismatch with NO end pending: refused before any launch, the checkpoint untouched
            nm_: dict[str, bool] = {}
            rq2 = fresh("pm_qual_nopending")
            _, exq0, _ = gate("Q-F0", "qual", QQ, rq2, adapter_for("Q-F0", "qual", QQ, None, cutq), lp="cached",
                              prior_ckpt=prior_time)
            cq2 = rq2 / "ckpt" / "Q-F0_qual.json"
            bq2 = cq2.read_bytes()
            rc2 = fresh("pm_camp_nopending")
            _, exc0, _ = camp("Q-F0", rc2, adapter_for("Q-F0", "campaign", S2, None, cutc), floors=S2, lcs=S2,
                              lp="cached")
            cc2 = rc2 / "ckpt" / "Q-F0_campaign.json"
            bc2 = cc2.read_bytes()
            for how, kw in (("--resume", {"resume": True}), ("plain", {})):
                adq_ = on_backend_y(adapter_for("Q-F0", "qual", QQ))
                _, eq_, tq_ = gate("Q-F0", "qual", QQ, rq2, adq_, lp="cached", prior_ckpt=prior_time, **kw)
                adc_ = on_backend_y(adapter_for("Q-F0", "campaign", S2))
                _, ec_, tc_ = camp("Q-F0", rc2, adc_, floors=S2, lcs=S2, lp="cached", **kw)
                nm_[how] = (isinstance(exq0, stages._Interrupt) and isinstance(exc0, stages._Interrupt)
                            and "end_pending" not in json.loads(bq2) and "end_pending" not in json.loads(bc2)
                            and isinstance(eq_, SystemExit) and "PATH MISMATCH (G-F0m-Qwen): the lock fixes the "
                                                                 "cached path" in str(eq_)
                            and isinstance(ec_, SystemExit) and "PATH MISMATCH (campaign-Q-F0): the lock fixes the "
                                                                 "cached path" in str(ec_)
                            and not adq_.calls and not adc_.calls and "PATH (" not in tq_ + tc_
                            and cq2.read_bytes() == bq2 and cc2.read_bytes() == bc2)
            chk("m_sessions: the same path mismatch with NO end pending (an interrupted qualification and "
                "campaign, locked cached, re-invoked on backend Y with --resume and plainly) is still refused PATH "
                "MISMATCH before any launch -- no PATH line, zero generate calls, the checkpoints byte-identical",
                all(nm_.values()), [n for n, ok in nm_.items() if not ok])
            # the drivers' own assertion: a re-finish-only invocation that finds no end pending after load
            rg2 = fresh("pm_gone")
            adg_ = on_backend_y(adapter_for("Q-F0", "qual", QQ))
            adc2_ = on_backend_y(adapter_for("Q-F0", "campaign", S2))
            with patched(stages, "_pending_on_disk", lambda p: True):
                _, eg_, _ = gate("Q-F0", "qual", QQ, rg2, adg_, lp="cached", prior_ckpt=prior_time)
                _, ec2_, _ = camp("Q-F0", rg2, adc2_, floors=S2, lcs=S2, lp="cached")
            chk("m_sessions: an invocation admitted as re-finish-only that finds no end pending once loaded is "
                "refused PATH MISMATCH by the qualification and the campaign drivers -- zero generate calls, no "
                "checkpoint written; stages' _pending_on_disk is restored after the substitution",
                all(isinstance(e, SystemExit) and "PATH MISMATCH" in str(e) and "is gone" in str(e)
                    for e in (eg_, ec2_))
                and not adg_.calls and not adc2_.calls and not (rg2 / "ckpt").exists()
                and stages._pending_on_disk.__name__ == "_pending_on_disk",
                (str(eg_)[:60], str(ec2_)[:60]))

        # --- G-PORT (step 5, m:275): the gport subcommand, on test directories only ---------------
        canon_g = guard.GATES_DIR / GPORT_NAME
        canon_before = canon_g.read_bytes() if canon_g.is_file() else None
        f1_rows = scaffold.load_f1_rows()
        corr_s = [r["session"] for r in f1_rows if r["arm"] == "CORR"]
        gdir = resume.refuse_canonical_out(base / "gport")
        rc_g, ex_g, txt_g = capture(main, ["gport", "--out", str(gdir)])
        lines_g = txt_g.splitlines()
        art_p = gdir / GPORT_NAME
        art_g = json.loads(art_p.read_text(encoding="utf-8")) if art_p.is_file() else {}
        want_art = {"criterion": GPORT_CRITERION, "unit": "Q-F0", "n_rows": 64, "n_ok": 64, "mismatches": [],
                    "f1_sessions_sha16": scaffold.F1_SESSIONS_SHA16, "package_sha256": resume.package_sha256(),
                    "verdict": "PASS"}
        chk("m_sessions: gport (G-PORT, m:275) on a temp dir -- all 64 archived CORR rows of data/f/sessions.jsonl "
            "(sha-pinned; the smoke file outside) replay: INVOCATION first, one 'gport s=<s> ok' per row in f1 "
            "order, last line '  G-PORT 64/64 archived CORR transcripts reproduced'; the artifact is exactly "
            "{criterion, unit, n_rows, n_ok, mismatches, f1_sessions_sha16, package_sha256, verdict PASS}; exit 0",
            rc_g == 0 and ex_g is None and len(corr_s) == 64 and lines_g[0].startswith("INVOCATION: ")
            and lines_g[1:-1] == [f"gport s={s} ok" for s in corr_s]
            and lines_g[-1] == "  G-PORT 64/64 archived CORR transcripts reproduced"
            and art_g == want_art and art_p.read_text(encoding="utf-8") == resume.json_text(want_art, indent=1),
            (rc_g, lines_g[-1:], {k: v for k, v in art_g.items() if want_art.get(k) != v}))
        pass_bytes = art_p.read_bytes() if art_p.is_file() else b""
        rc_g2, _, txt_g2 = capture(main, ["gport", "--out", str(gdir)])
        tam = json.loads(json.dumps(f1_rows))
        t_row = [r for r in tam if r["arm"] == "CORR" and r["session"] == 5][0]
        t_row["transcript"] = t_row["transcript"].replace("Response:", "Response;", 1)
        tam_sha = hashlib.sha256("".join(json.dumps(r) + "\n" for r in tam).encode()).hexdigest()[:16]
        gdir_t = resume.refuse_canonical_out(base / "gport_tampered")
        rc_t, _, txt_t = capture(run_gport, gdir_t, rows=tam, f1_sha16=tam_sha)
        art_t = json.loads((gdir_t / GPORT_NAME).read_text(encoding="utf-8"))
        short = [r for r in f1_rows if not (r["arm"] == "CORR" and r["session"] == 63)]
        gdir_s = resume.refuse_canonical_out(base / "gport_short")
        rc_s, _, txt_s = capture(run_gport, gdir_s, rows=short, f1_sha16="0" * 16)
        art_s = json.loads((gdir_s / GPORT_NAME).read_text(encoding="utf-8"))
        mism_line = [ln for ln in txt_t.splitlines() if "MISMATCH" in ln]
        chk("m_sessions: gport STOPs (exit 4) on a tampered archived row -- 'gport s=5 MISMATCH: <problems>', "
            "63/64, the artifact's mismatches name s 5 and verdict STOP -- and on a row list one CORR row short "
            "(63/63 reproduced is not 64/64); a re-run over an identical artifact changes nothing (exit 0)",
            rc_t == 4 and len(mism_line) == 1 and mism_line[0].startswith("gport s=5 MISMATCH: ")
            and txt_t.splitlines()[-1] == "  G-PORT 63/64 archived CORR transcripts reproduced"
            and art_t["verdict"] == "STOP" and art_t["n_ok"] == 63 and art_t["n_rows"] == 64
            and [m["s"] for m in art_t["mismatches"]] == [5] and art_t["mismatches"][0]["problems"]
            and art_t["f1_sessions_sha16"] == tam_sha
            and rc_s == 4 and art_s["verdict"] == "STOP" and (art_s["n_ok"], art_s["n_rows"]) == (63, 63)
            and art_s["mismatches"] == [] and txt_s.splitlines()[-1] == "  G-PORT 63/63 archived CORR transcripts reproduced"
            and rc_g2 == 0 and art_p.read_bytes() == pass_bytes,
            (rc_t, mism_line[:1], rc_s, rc_g2))
        err_g = io.StringIO()
        with contextlib.redirect_stderr(err_g):
            rc_o, _, txt_o = capture(run_gport, gdir, rows=tam, f1_sha16=tam_sha)
            rc_c, ex_c, _ = capture(main, ["gport", "--out", str(REPO / "data" / "m" / "gates")])
            rc_r, ex_r, _ = capture(run_gport, None, rows=tam, f1_sha16=tam_sha)
            rc_b, _, _ = capture(main, ["--build-schedules", "gport", "--out", str(base / "gport_combo")])
        chk("m_sessions: gport never overwrites an artifact with different bytes (refused, exit 1, the PASS "
            "artifact byte-identical); --out under data/m is refused (SELFTEST REFUSED) before anything runs; "
            "supplied rows never reach the canonical path; gport refuses a combined --build-schedules (exit 2); "
            "the canonical data/m/gates artifact is untouched by the selftest",
            rc_o == 1 and "REFUSED: G-PORT ARTIFACT EXISTS" in err_g.getvalue() and art_p.read_bytes() == pass_bytes
            and isinstance(ex_c, SystemExit) and "SELFTEST REFUSED" in str(ex_c) and rc_c is None
            and isinstance(ex_r, SystemExit) and "G-PORT REFUSED" in str(ex_r)
            and rc_b == 2 and not (base / "gport_combo").exists()
            and (canon_g.read_bytes() if canon_g.is_file() else None) == canon_before,
            (rc_o, str(ex_c)[:50], str(ex_r)[:50], rc_b))

        # gport --out "" -- Path("") is "." (the working directory): refused on the raw string.
        # Run from a temp cwd so a regression could never write into the repo.
        ecwd = base / "gport_emptyout_cwd"
        ecwd.mkdir()
        here = os.getcwd()
        try:
            os.chdir(ecwd)
            with contextlib.redirect_stderr(io.StringIO()):
                rc_e, ex_e, _ = capture(main, ["gport", "--out", ""])
                rc_w, ex_w, _ = capture(main, ["gport", "--out", "   "])
        finally:
            os.chdir(here)
        chk("m_sessions: gport --out '' (and a blank --out) is refused before any replay -- an empty path "
            "would resolve to the working directory; nothing is written there or at the repo root",
            isinstance(ex_e, SystemExit) and "empty path is refused" in str(ex_e)
            and isinstance(ex_w, SystemExit) and "empty path is refused" in str(ex_w)
            and not any(ecwd.iterdir()) and not (REPO / "Q-F0_G-PORT.json").exists(),
            (str(ex_e)[:60], sorted(x.name for x in ecwd.iterdir())))

        # --- G-CAL (step 6, m:176): the gcal subcommands, on test directories only; the Qwen
        # loader is replaced by a sentinel that fails the check if it is ever called -------------
        from valence_core.m import gcal
        # each canonical G-CAL path's bytes (or its absence) before these checks; compared after
        gsnap0 = gcal.canonical_snapshot()
        loads: list[int] = []

        def no_load():
            loads.append(1)
