        mq_noruling = {k_: q_safe(k_, lambda: time_qwen(f"cm_unreadable_nr_{i_}", lic=[], more=no_prior,
                                                        setup=c_bytes(v_), cmd="campaign", snap=qs_,
                                                        resume_flag=True))
                       for i_, (k_, v_) in enumerate((("a non-empty pauses block that is not a list",
                                                       json.dumps(ck_nl).encode()),
                                                      ("an earlier pause's adjudication that cannot be encoded",
                                                       json.dumps(ck_ep).encode())))
                       if not screen_raises(f"n{i_}", k_, v_)}
        # the refusal's scope is the campaign's (the preview's e16): an unreadable G-TIME-F0 checkpoint with --resume
        # still reaches the loader -- its readability refusal is the stage's, after the load (HEAD's v0.2 PIN)
