        # a campaign checkpoint path whose stat fails (round 4's O4-3; ENAMETOOLONG stands in for EACCES, which root
        # cannot provoke): _campaign_state reads it as unreadable, and the campaign's precheck refuses it through the
        # checkpoint block's own label ('does not resolve'), with no traceback, offered a ruling and not
